153			},
154			workflow: (name: string | { scriptPath: string }, a?: unknown) => globals.workflow(name, a),
155	
156			// Allowed structured-data globals
157			Promise,
158			Array,
159			Object,
160			String,
161			Number,
162			Boolean,
163			Map,
164			Set,
165			WeakMap,
166			WeakSet,
167			JSON,
168			Symbol,
169			RegExp,
170			Error,
171			TypeError,
172			RangeError,
173			console: {
174				log: (msg: unknown) => globals.log(String(msg)),
175				error: (msg: unknown) => globals.log(`[error] ${String(msg)}`),
176				warn: (msg: unknown) => globals.log(`[warn] ${String(msg)}`),
177				info: (msg: unknown) => globals.log(String(msg)),
