195			queueMicrotask: () => throwDeterminism("queueMicrotask", RESUME_RATIONALE),
196			clearTimeout: () => {},
197			clearInterval: () => {},
198	
199			// Forbidden direct I/O
200			fetch: () => throwDeterminism("fetch", "use agent() with a web-capable agent instead"),
201			require: () => throwDeterminism("require()", "workflow scripts cannot import modules"),
202		};
