221	/**
222	 * Compile + run a workflow script in the given sandbox.
223	 *
224	 * The script can be either an ES-module body (using `export` / top-level await)
225	 * or a script body. We wrap it in an async IIFE that returns the last
226	 * expression, so plain scripts work without ceremony.
227	 *
228	 * Returns whatever the script ultimately resolves to.
229	 */
230	export async function runWorkflowScript(
231		source: string,
232		context: vm.Context,
233		opts: { syncTimeoutMs: number; wallTimeoutMs?: number; filename: string },
234	): Promise<unknown> {
235		if (source.length > 50_000) {
236			throw new Error(`Workflow script too large (${source.length} bytes; max 50000).`);
237		}
238	
239		// Static determinism pre-scan (Claude Code 2.1.153): reject obvious clock /
240		// randomness reads before launch, in addition to the runtime shims below.
241		if (/\bDate\s*\.\s*now\b|\bMath\s*\.\s*random\b|\bnew\s+Date\s*\(\s*\)/.test(source)) {
242			throw new DeterminismViolation(
243				"Date.now()/Math.random()/new Date()",
244				"breaks resume. Stamp results after the workflow returns, or pass timestamps via args.",
245			);
246		}
247	
248		const stripped = stripModuleSyntax(source);
249		const wrapped = `(async () => {\n${stripped}\n})()`;
250	
251		const script = new vm.Script(wrapped, {
252			filename: opts.filename,
253			// Pre-compile catches syntax errors before we incur the run timeout.
254		});
255	
256		// `syncTimeoutMs` bounds SYNCHRONOUS runaway only (vm timeout is per-call and
257		// sync-only; the async wrapper is sync until the first await) — a guard against
258		// an infinite JS loop blocking the event loop.
259		const runPromise = script.runInContext(context, { timeout: opts.syncTimeoutMs, breakOnSigint: true });
260	
261		// `wallTimeoutMs` is a separate, generous overall cap on the async run. Claude
262		// Code imposes no short script timeout — it governs long workflows by token
263		// budget + the agent() lifetime cap + async execution. So we keep this large for
264		// foreground runs and skip it entirely (0/undefined) for background runs, which
265		// are governed by the agent cap and aborted on session dispose.
266		if (!opts.wallTimeoutMs || opts.wallTimeoutMs <= 0) {
267			return runPromise;
268		}
269		const wall = opts.wallTimeoutMs;
270		const timeoutPromise = new Promise<never>((_, reject) => {
271			const id = global.setTimeout(() => reject(new Error(`Workflow execution exceeded ${wall}ms`)), wall);
272			// Allow Node to exit if the workflow completes before timeout
273			id.unref?.();
274		});
275	
276		return Promise.race([runPromise, timeoutPromise]);
277	}
278	
279	/**
280	 * Strip `export` declarations and bare `import` statements so the script can be
281	 * evaluated as a regular Function body inside our IIFE. We don't try to be a
282	 * real bundler — we just need `export const meta = {…}` and `// ...` comments
283	 * to survive eval.
284	 *
285	 * Conversions:
286	 *   `export const meta = {...}` → `globalThis.__meta = {...}`
287	 *   `export default X`          → `return X`
288	 *   `export { ... }`            → `// removed: export {...}`
289	 *   `import ...`                → throws (workflows can't import)
290	 */
291	function stripModuleSyntax(source: string): string {
292		if (/^\s*import\s/m.test(source)) {
293			throw new Error("Workflow scripts cannot use `import`. Use agent() / workflow() instead.");
294		}
295	
296		return source
297			.replace(/^\s*export\s+default\s+/gm, "return ")
298			.replace(/^\s*export\s+const\s+meta\s*=/gm, "globalThis.__meta =")
299			.replace(/^\s*export\s+\{[^}]*\};?\s*$/gm, "")
300			.replace(/^\s*export\s+/gm, ""); // `export const x` → `const x`
301	}
