350					path: resolved.path,
351				});
352				// Seed the new run's journal with replayed steps so it stays self-contained
353				// (a resume of a resume reads one journal, not a chain).
354				for (const [key, value] of replay) appendJournal(ctx.cwd, runId, key, value);
355	
356				// Deterministic call-path scope for journal keys (see helpers above).
357				const rootScope: CallScope = { path: "", counter: { n: 0 } };
358				const currentScope = (): CallScope => callScopeStore.getStore() ?? rootScope;
359				const nextCallKey = (): string => {
360					const scope = currentScope();
361					return `${scope.path}#${scope.counter.n++}`;
362				};
363	
364				const logs: string[] = [];
365				const phases: string[] = [];
366				const agentCalls: WorkflowAgentCallRecord[] = [];
367				let agentCount = 0;
368	
369				if (resolved.origin !== "inline") {
370					// Surface what we're running so the model can reason about it.
371					// Inline scripts log themselves implicitly via the source preview.
372				}
373	
374				const pushLog = (line: string) => {
375					if (logs.length < LOG_LINE_CAP) logs.push(line);
376					emitUpdate();
377				};
378	
379				// Set once the run settles (success/error/timeout) or for background runs.
380				// A late progress update — e.g. an in-flight parallel() fork settling after
381				// the script already errored/timed out — must NOT call onUpdate: that pushes
382				// into a turn that's already closed and crashes the process with
383				// "Agent listener invoked outside active run".
384				let settled = false;
385				const emitUpdate = () => {
386					if (!onUpdate || settled) return;
387					const partial: WorkflowDetails = {
388						runId,
389						scriptPath,
390						source: "inline",
391						phases: [...phases],
392						agentCount,
393						logs: [...logs],
394						agentCalls: [...agentCalls],
395						startedAt,
396						durationMs: Date.now() - startedAt,
397					};
398					try {
399						onUpdate({
400							content: [{ type: "text", text: `Workflow ${runId}${resolved.name ? ` (${resolved.name})` : ""}: ${agentCount} agent(s), ${logs.length} log(s)` }],
401							details: partial as unknown as AgentToolDetails,
402						});
403					} catch {
404						// Run already settled; the final tool result carries the details.
405					}
406				};
407	
408				const budgetState = { spent: 0, total: DEFAULT_TASK_BUDGET_TOKENS as number | null };
409				// One run-scoped controller drives every subagent fork. Sync runs chain the
410				// turn signal so a user abort propagates; background runs swap in a detached
411				// controller below so subagents survive past the launching turn. Aborted when
412				// the run settles so lingering parallel() forks (after an error/timeout) are
413				// cancelled instead of settling later and emitting into a closed turn.
414				const runController = new AbortController();
415				if (signal) {
416					if (signal.aborted) runController.abort();
417					else signal.addEventListener("abort", () => runController.abort(), { once: true });
418				}
419				let runSignal: AbortSignal = runController.signal;
420				const globals: SandboxGlobals = {
421					args: input.args,
422					log: (msg) => pushLog(msg),
423					phase: (title) => {
424						phases.push(title);
425						pushLog(`── ${title} ──`);
426					},
427					budget: {
428						get total() {
429							return budgetState.total;
430						},
431						spent: () => budgetState.spent,
432						remaining: () => (budgetState.total === null ? Infinity : Math.max(0, budgetState.total - budgetState.spent)),
433					},
434					agent: async (prompt, opts = {}) => {
435						// Key is assigned synchronously at call entry → deterministic
436						// order even for concurrent calls (the array is built in order).
437						const key = nextCallKey();
438						if (replay.has(key)) {
439							agentCalls.push({
440								seq: agentCalls.length,
441								prompt,
442								label: opts.label as string | undefined,
443								model: opts.model as string | undefined,
444								durationMs: 0,
445								resultPreview: "(replayed from journal)",
446								status: "replayed",
447							});
448							pushLog(`↺ replayed ${key}`);
449							emitUpdate();
450							return replay.get(key) as string | object;
451						}
452						if (agentCount >= AGENT_LIFETIME_CAP) {
453							// Message mirrors Claude Code 2.1.153.
454							throw new Error(
455								`Workflow agent() call cap reached (${AGENT_LIFETIME_CAP}). This usually means a loop using budget.remaining() never terminates. Add a hard iteration cap to the loop, or pass a token budget.`,
456							);
457						}
458						agentCount++;
459						// Live record so the TUI tree shows the subagent as it runs, then
460						// flips it to done/error in place when it settles.
461						const liveIndex =
462							agentCalls.push({
463								seq: agentCalls.length,
464								prompt,
465								label: opts.label as string | undefined,
466								model: opts.model as string | undefined,
467								durationMs: 0,
468								resultPreview: "",
469								status: "running",
470							}) - 1;
471						emitUpdate();
472						const result = await runAgent(ctx, prompt, opts, runSignal, (record) => {
473							agentCalls[liveIndex] = {
474								...record,
475								seq: agentCalls[liveIndex].seq,
476								status: record.error ? "error" : "done",
477							};
478							budgetState.spent += record.tokens ?? 0;
479							emitUpdate();
480						});
481						appendJournal(ctx.cwd, runId, key, result);
482						return result;
483					},
484					parallel: async <T>(tasks: Array<() => Promise<T>>) => {
485						const parent = currentScope();
486						return runParallel(
487							tasks.map((task, i) => () =>
488								callScopeStore.run({ path: `${parent.path}/p${i}`, counter: { n: 0 } }, task),
489							),
490							PARALLEL_DEFAULT_CONCURRENCY,
491						);
492					},
493					pipeline: async <T>(stages: Array<() => Promise<T>>) => {
494						const parent = currentScope();
495						const out: T[] = [];
496						for (let i = 0; i < stages.length; i++) {
497							out.push(await callScopeStore.run({ path: `${parent.path}/s${i}`, counter: { n: 0 } }, stages[i]));
498						}
499						return out;
500					},
501					workflow: async () => {
502						throw new Error("Nested workflow() not supported in phase 1. See DESIGN.md phase 5.");
503					},
504				};
505	
506				emitUpdate();
507	
508				// Background runs skip the wall cap (governed by the agent cap + session
509				// dispose); foreground runs get a generous overall cap.
510				const wallTimeoutMs = input.background ? 0 : FOREGROUND_WALL_TIMEOUT_MS;
511				const runOnce = async (): Promise<AgentToolResult<AgentToolDetails> & { isError?: boolean }> => {
512				try {
513					const context = buildSandboxContext(globals);
514					const result = await runWorkflowScript(resolved.source, context, {
515						syncTimeoutMs: SYNC_TIMEOUT_MS,
516						wallTimeoutMs,
517						filename: `${runId}.js`,
518					});
519					const durationMs = Date.now() - startedAt;
520					const details: WorkflowDetails = {
521						runId,
522						scriptPath,
523						source: resolved.origin,
524						name: resolved.name,
525						phases,
526						agentCount,
527						logs,
528						agentCalls,
529						startedAt,
530						durationMs,
531					};
532					writeRunMeta(ctx.cwd, runId, { status: "completed", details, result });
533	
534					return {
535						content: [
536							{
537								type: "text",
538								text: formatCompletion(details, result),
539							},
540						],
541						details: details as unknown as AgentToolDetails,
542					};
543				} catch (e) {
544					const err = e as Error;
545					const durationMs = Date.now() - startedAt;
546					const details: WorkflowDetails = {
547						runId,
548						scriptPath,
549						source: resolved.origin,
550						name: resolved.name,
551						phases,
552						agentCount,
553						logs,
554						agentCalls,
555						startedAt,
556						durationMs,
557						error: err.message,
558					};
559					writeRunMeta(ctx.cwd, runId, { status: "error", details, error: err.message });
560	
561					const label = err instanceof DeterminismViolation ? "Determinism violation" : "Workflow error";
562					return {
563						content: [
564							{
565								type: "text",
566								text: `${label} in ${runId}:\n${err.message}\n\nScript persisted at ${scriptPath} for inspection.`,
567							},
568						],
569						details: details as unknown as AgentToolDetails,
570						isError: true,
571					};
572				} finally {
573					// Stop emitting and cancel any still-in-flight forks (e.g. parallel()
574					// siblings after one threw, or subagents alive past a wall timeout) so
575					// they never settle into a closed turn.
576					settled = true;
577					runController.abort();
578				}
579				};
580	
581				if (input.background) {
582					// Background progress is persisted to meta.json and read via checkRunId;
583					// it must never call onUpdate (the launching turn has already returned).
584					settled = true;
585					const controller = new AbortController();
586					runSignal = controller.signal;
587					writeRunMeta(ctx.cwd, runId, {
588						status: "running",
589						details: {
590							runId,
591							scriptPath,
592							source: resolved.origin,
593							name: resolved.name,
594							phases,
595							agentCount,
596							logs,
597							agentCalls,
598							startedAt,
599							durationMs: 0,
600						},
601					});
602					const promise = runOnce()
603						.catch(() => {})
604						.finally(() => backgroundRuns.delete(runId));
605					backgroundRuns.set(runId, { controller, promise, startedAt });
606					return {
607						content: [
608							{
609								type: "text",
610								text: `Workflow ${runId} launched in background${resolved.name ? ` (${resolved.name})` : ""}. Poll with Workflow({ checkRunId: "${runId}" }).`,
611							},
612						],
613						details: {
614							runId,
615							scriptPath,
616							source: resolved.origin,
617							name: resolved.name,
618							phases: [],
619							agentCount: 0,
620							logs: [],
621							agentCalls: [],
622							startedAt,
623							durationMs: 0,
624						} as unknown as AgentToolDetails,
625					};
626				}
627	
628				return runOnce();
629			},
630	
631			renderCall(args, theme) {
632				const input = args as WorkflowInput;
633				if (input.name) {
634					return new Text(
635						theme.fg("toolTitle", theme.bold("Workflow ")) + theme.fg("accent", input.name),
