668		// /workflows slash command: lists available workflows by source.
669	
670		// Shared by /workflows and the no-arg /workflow: browse → pick → show detail.
671		const openWorkflowPicker = async (ctx: any): Promise<void> => {
672			const all = discoverWorkflows(ctx.cwd);
673			if (all.length === 0) {
674				ctx.ui.notify("No workflows discovered. Add scripts to ~/.pi/agent/workflows/ or ./.pi/workflows/.", "info");
675				return;
676			}
677	
678			const groups: Record<string, typeof all> = { builtin: [], user: [], project: [] };
679			for (const w of all) groups[w.source].push(w);
680	
681			const lines: string[] = [];
682			for (const src of ["project", "user", "builtin"] as const) {
683				if (groups[src].length === 0) continue;
684				lines.push(`--- ${src} (${groups[src].length}) ---`);
685				for (const w of groups[src]) {
686					lines.push(`${w.name} — ${w.meta.description}`);
687				}
688			}
689	
690			const picked = await ctx.ui.select("Workflows", lines);
691			if (!picked || picked.startsWith("---")) return;
692	
693			const name = picked.split(" — ")[0];
694			const found = all.find((w) => w.name === name);
695			if (!found) return;
696			ctx.ui.notify(formatWorkflowDetail(found), "info");
697		};
698	
699		pi.registerCommand("workflows", {
700			description: "List available pi-workflow scripts (built-in / user / project)",
701			handler: async (_args, ctx) => openWorkflowPicker(ctx),
702		});
703	
704		// /workflow (singular): direct detail, scaffold-new, or browse (reuses picker).
705		wireWorkflowCommand(pi, openWorkflowPicker);
706	}
