708	const AGENT_TREE_CAP = 12;
709	
710	function agentStatusIcon(rec: WorkflowAgentCallRecord, theme: any): string {
711		switch (rec.status) {
712			case "running":
713				return theme.fg("accent", "●");
714			case "error":
715				return theme.fg("error", "✗");
716			case "replayed":
717				return theme.fg("muted", "↻");
718			default:
719				return rec.error ? theme.fg("error", "✗") : theme.fg("success", "✓");
720		}
721	}
722	
723	function agentTreeLabel(rec: WorkflowAgentCallRecord): string {
724		const base = (rec.label ?? rec.prompt).replace(/\s+/g, " ").trim();
725		return base.length > 48 ? `${base.slice(0, 47)}…` : base;
726	}
727	
728	// Live progress tree: one line per subagent with status icon, label, model and
729	// duration (or "running…"). Capped so a fan-out of hundreds stays readable.
730	function agentTreeLines(details: WorkflowDetails, theme: any): string[] {
731		const calls = details.agentCalls;
732		const lines: string[] = [];
733		let shown = calls;
734		if (calls.length > AGENT_TREE_CAP) {
735			lines.push(`  ${theme.fg("muted", `… ${calls.length - AGENT_TREE_CAP} earlier agent(s)`)}`);
736			shown = calls.slice(-AGENT_TREE_CAP);
737		}
738		shown.forEach((rec, i) => {
739			const branch = theme.fg("dim", i === shown.length - 1 ? "└─" : "├─");
740			const model = rec.model ? theme.fg("dim", ` ${rec.model}`) : "";
741			const meta =
742				rec.status === "running"
743					? theme.fg("muted", " running…")
744					: theme.fg("muted", ` ${rec.durationMs}ms`);
745			lines.push(`  ${branch} ${agentStatusIcon(rec, theme)} ${agentTreeLabel(rec)}${model}${meta}`);
746		});
747		return lines;
748	}
749	
750	function renderWorkflowResult(result: any, theme: any): any {
751		const details = result.details as unknown as WorkflowDetails | undefined;
752		if (!details) {
753			const t = result.content[0];
754			return new Text(t?.type === "text" ? t.text : "(no output)", 0, 0);
755		}
756		const running = details.agentCalls.some((rec) => rec.status === "running");
757		const icon = details.error
758			? theme.fg("error", "✗")
759			: running
760				? theme.fg("accent", "●")
761				: theme.fg("success", "✓");
762		const label = details.name ? `${details.runId} (${details.name})` : details.runId;
763		const head =
764			icon +
765			" " +
766			theme.fg("toolTitle", theme.bold("Workflow ")) +
767			theme.fg("accent", label) +
768			theme.fg(
769				"muted",
770				` · ${details.agentCount} agent${details.agentCount === 1 ? "" : "s"} · ${details.durationMs}ms`,
771			);
772		const phasesLine = details.phases.length
773			? `\n  ${theme.fg("muted", "phases:")} ${details.phases.join(" → ")}`
774			: "";
775		const err = details.error ? `\n  ${theme.fg("error", details.error)}` : "";
776		return new Text([head + phasesLine + err, ...agentTreeLines(details, theme)].join("\n"), 0, 0);
777	}
