789	function persistScript(
790		cwd: string,
791		runId: string,
792		source: string,
793		origin?: { origin: "inline" | "named" | "persisted"; name?: string; path?: string },
794	): string {
795		const dir = path.join(cwd, ".pi", "workflows", "runs", runId);
