813	/**
814	 * Resolve the workflow source from a tool input: inline `code`, named lookup,
815	 * or persisted scriptPath. Returns either the resolved source bundle or an
816	 * error message ready for surface back to the model.
817	 */
818	function resolveSource(
819		input: WorkflowInput,
820		cwd: string,
821	):
822		| { origin: "inline" | "named" | "persisted"; source: string; name?: string; path?: string }
823		| { error: string } {
824		const scriptSource = input.script ?? input.code; // `code` is the legacy 2.1.146 alias
825		const supplied = [scriptSource ? "script" : null, input.name ? "name" : null, input.scriptPath ? "scriptPath" : null].filter(
826			(k): k is string => Boolean(k),
827		);
828		if (supplied.length === 0) {
829			// Verbatim Claude Code 2.1.153 validation message.
830			return { error: "Must provide script, name, or scriptPath" };
831		}
832		if (supplied.length > 1) {
833			return { error: `Pass exactly one of script/name/scriptPath, got: ${supplied.join(", ")}.` };
834		}
835		if (scriptSource) {
836			const metaErr = requireMetaHeader(scriptSource);
837			if (metaErr) return { error: metaErr };
838			return { origin: "inline", source: scriptSource };
839		}
840		if (input.name) {
841			const hit = findWorkflowByName(cwd, input.name);
842			if (!hit) {
843				const all = discoverWorkflows(cwd);
844				const available = all.map((w) => `${w.name} (${w.source})`).join(", ") || "(none)";
845				return { error: `Workflow '${input.name}' not found. Available: ${available}.` };
846			}
847			try {
848				return { origin: "named", source: loadWorkflowSource(hit.path), name: hit.name, path: hit.path };
849			} catch (e) {
850				return { error: `Failed to load workflow '${input.name}' from ${hit.path}: ${(e as Error).message}` };
851			}
852		}
853		if (input.scriptPath) {
854			if (!fs.existsSync(input.scriptPath)) {
855				return { error: `scriptPath does not exist: ${input.scriptPath}` };
856			}
857			try {
858				return { origin: "persisted", source: loadWorkflowSource(input.scriptPath), path: input.scriptPath };
859			} catch (e) {
860				return { error: `Failed to read scriptPath ${input.scriptPath}: ${(e as Error).message}` };
861			}
862		}
863		return { error: "Unreachable: no source resolved." };
864	}
