867		cwd: string,
868		runId: string,
869		body: Record<string, unknown>,
870	): void {
871		const dir = path.join(cwd, ".pi", "workflows", "runs", runId);
872		try {
873			fs.writeFileSync(path.join(dir, "meta.json"), JSON.stringify(body, null, 2), { mode: 0o600 });
874		} catch {
875			/* best-effort */
876		}
877	}
