879	async function runAgent(
880		ctx: ExtensionContext,
881		prompt: string,
882		opts: Record<string, unknown>,
883		parentSignal: AbortSignal | undefined,
884		onComplete: (record: WorkflowAgentCallRecord) => void,
885	): Promise<string | object> {
886		const t0 = Date.now();
887		const label = typeof opts.label === "string" ? opts.label : undefined;
888		const model = typeof opts.model === "string" ? opts.model : undefined;
889		const agentType = typeof opts.agentType === "string" ? opts.agentType : undefined;
890		const allowedTools = Array.isArray(opts.allowedTools) ? (opts.allowedTools as string[]) : undefined;
891		const schema = isObject(opts.schema) ? opts.schema : undefined;
892	
893		// Structured output rides back via the StructuredOutput tool call (CC 1:1).
894		// Seed a rendezvous slot the child's tool writes into; correlate via metadata.
895		const structuredCallId = schema ? `so_${crypto.randomBytes(8).toString("hex")}` : undefined;
896		if (structuredCallId) structuredOutputCaptures.set(structuredCallId, { captured: false });
897	
898		const subagentPrompt = schema ? `${prompt}${structuredOutputInstruction(schema)}` : prompt;
899	
900		// Optional git-worktree isolation: the subagent runs in a throwaway worktree
901		// off HEAD, removed when it settles. Requires a git working tree.
902		let worktree: WorktreeHandle | undefined;
903		if (opts.isolation === "worktree") {
904			if (!isGitWorkTree(ctx.cwd)) {
905				throw new Error('agent({ isolation: "worktree" }) requires the workflow cwd to be a git working tree.');
906			}
907			worktree = createWorktree(ctx.cwd, label);
908		}
909	
910		// Cache-stability (see pi-cache-stability skill): the subagent prefix is the
911		// byte-identical WORKFLOW_SUBAGENT_SYSTEM + tool schemas. `context: "none"`
912		// drops the parent's mutable auto-built prompt (cwd/date/skills/transcript),
913		// so every workflow subagent across every session/cwd shares one warm cache
914		// entry. Per-call dynamic data lives in the user `prompt`. This also matches
915		// Claude Code 2.1.153, whose workflow-subagent uses exactly this system
916		// prompt with no parent context.
917		//
918		// When the caller routes a named agent type (e.g. agent({ agent: "explore" })),
919		// hand the child to that definition instead: drop the forced system prompt so
920		// the executor applies the agent's own stable append + tools + model (cheap
921		// read-only explore vs. the default general/opus child). Stable agents
922		// (cacheProfile: "stable") keep a warm per-type cache entry under context:"none".
923		const { handle } = await ctx.forkAgent({
924			prompt: subagentPrompt,
925			agentType,
926			systemPrompt: agentType ? undefined : WORKFLOW_SUBAGENT_SYSTEM,
927			context: "none",
928			allowedTools,
929			model,
930			signal: parentSignal,
931			description: label ?? "workflow-subagent",
932			silent: true,
933			// Lets this extension, running inside the child, recognise the fork and
934			// register the StructuredOutput return tool for this specific call.
935			metadata: structuredCallId ? { [STRUCTURED_OUTPUT_META_KEY]: structuredCallId } : undefined,
936			// Isolation: run the subagent inside the throwaway worktree (core seam).
937			cwd: worktree?.path,
938		});
939	
940		try {
941			const details = await handle.wait();
942			const text = extractFinalText(details);
943			const durationMs = Date.now() - t0;
944			const record: WorkflowAgentCallRecord = {
945				seq: -1,
946				prompt,
947				label,
948				model,
949				durationMs,
950				resultPreview: text.slice(0, 200),
951				tokens: (details.runs?.[0]?.usage as { totalTokens?: number } | undefined)?.totalTokens ?? 0,
952			};
953			onComplete(record);
954			if (schema) {
955				const entry = structuredCallId ? structuredOutputCaptures.get(structuredCallId) : undefined;
956				if (structuredCallId) structuredOutputCaptures.delete(structuredCallId);
957				if (entry?.captured) return entry.value as object;
958				// Fallback for a subagent that answered in text instead of calling the
959				// tool (e.g. an older model): keep the prior JSON-from-text behaviour.
960				try {
961					return JSON.parse(text);
962				} catch {
963					throw new Error(
964						`Subagent did not return structured output via ${STRUCTURED_OUTPUT_TOOL} or valid JSON. Got: ${text.slice(0, 400)}`,
965					);
966				}
967			}
968			return text;
969		} catch (e) {
970			if (structuredCallId) structuredOutputCaptures.delete(structuredCallId);
971			const err = e as Error;
972			const durationMs = Date.now() - t0;
973			const record: WorkflowAgentCallRecord = {
974				seq: -1,
975				prompt,
976				label,
977				model,
978				durationMs,
979				resultPreview: "",
980				error: err.message,
981			};
982			onComplete(record);
983			throw err;
984		} finally {
985			if (worktree) removeWorktree(ctx.cwd, worktree);
986		}
987	}
988	
989	function extractFinalText(details: AgentToolDetails): string {
990		// AgentToolDetails.runs[] contains AgentRunDetails with finalOutput/rawOutput.
991		// For a single forked agent there's exactly one run.
992		const run = details.runs?.[0];
993		if (!run) return "";
994		if (run.error) throw new Error(`Subagent failed: ${run.error}`);
995		return run.finalOutput ?? run.rawOutput ?? "";
996	}
997	
998	async function runParallel<T>(tasks: Array<() => Promise<T>>, concurrency: number): Promise<T[]> {
999		if (tasks.length === 0) return [];
1000		const limit = Math.max(1, Math.min(concurrency, tasks.length));
1001		const results: T[] = new Array(tasks.length);
1002		let nextIndex = 0;
1003		const workers = new Array(limit).fill(null).map(async () => {
1004			while (true) {
1005				const i = nextIndex++;
1006				if (i >= tasks.length) return;
1007				results[i] = await tasks[i]();
1008			}
1009		});
1010		await Promise.all(workers);
1011		return results;
1012	}
1013	
1014	function formatCompletion(details: WorkflowDetails, result: unknown): string {
1015		const head = `Workflow ${details.runId} completed in ${details.durationMs}ms (${details.agentCount} agent${details.agentCount === 1 ? "" : "s"}).`;
1016		const phases = details.phases.length ? `\nPhases: ${details.phases.join(" → ")}` : "";
1017		const logTail = details.logs.length ? `\n\nLast ${Math.min(5, details.logs.length)} log lines:\n${details.logs.slice(-5).map((l) => `  ${l}`).join("\n")}` : "";
1018		const resultStr =
1019			result === undefined
1020				? ""
1021				: typeof result === "string"
1022					? `\n\nResult:\n${result}`
1023					: `\n\nResult:\n${JSON.stringify(result, null, 2)}`;
1024		return `${head}${phases}${logTail}${resultStr}\n\nScript: ${details.scriptPath}`;
1025	}
1026	
1027	function isObject(v: unknown): v is Record<string, unknown> {
1028		return v !== null && typeof v === "object" && !Array.isArray(v);
1029	}
1030	
1031	/**
1032	 * Claude Code 2.1.153 requires every workflow script (inline or named) to begin
1033	 * with a pure-literal `export const meta = {...}` header. We allow leading
1034	 * comments/whitespace before the export. Returns an error string or null.
1035	 */
1036	function requireMetaHeader(source: string): string | null {
1037		const withoutLeading = source.replace(/^(?:\s|\/\/[^\n]*\n|\/\*[\s\S]*?\*\/)*/, "");
1038		if (/^export\s+const\s+meta\s*=\s*\{/.test(withoutLeading)) return null;
1039		return "Script must begin with `export const meta = { name, description, phases }` (pure literal).";
1040	}
1041

