/**
 * pi-workflow — deterministic JavaScript workflow orchestrator.
 *
 * Clones Claude Code 2.1.146's Workflow tool, adapted to pi's `ctx.forkAgent`
 * primitive.
 *
 * Surface:
 *   - `code` (inline JS), `name` (built-in/user/project workflow), or `scriptPath` (re-run a persisted run).
 *   - VM sandbox with shimmed Date/Math.random/timers.
 *   - Globals: args, log, phase, budget, agent, parallel, pipeline, workflow.
 *   - `agent()` uses ctx.forkAgent.
 *   - Synchronous execution; result returned inline.
 *   - `/workflows` slash command lists everything available.
 *
 * See DESIGN.md for the multi-phase roadmap.
 */

import { AsyncLocalStorage } from "node:async_hooks";
import { execFileSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import * as crypto from "node:crypto";
import type {
	AgentHandle,
	AgentToolResult,
	ExtensionAPI,
	ExtensionContext,
} from "@earendil-works/pi-coding-agent";

type AgentToolDetails = Awaited<ReturnType<AgentHandle["wait"]>>;
import { Text } from "@earendil-works/pi-tui";
import { Type } from "typebox";
import { buildSandboxContext, DeterminismViolation, runWorkflowScript, type SandboxGlobals } from "./sandbox.ts";
import { discoverWorkflows, findWorkflowByName, loadWorkflowSource } from "./discovery.ts";
import { wireUltracode } from "./ultracode.ts";
import { wireWorkflowKeyword } from "./workflow-keyword.ts";
import { wireWorkflowCommand, formatWorkflowDetail } from "./workflow-command.ts";
import type { WorkflowAgentCallRecord, WorkflowDetails, WorkflowInput } from "./types.ts";

// Bounds synchronous runaway only (vm sync timeout): an infinite JS loop in the
// script. Live-model agent() calls are async and not counted here.
const SYNC_TIMEOUT_MS = 30_000;
// Generous overall wall cap for FOREGROUND runs so a hung turn can't block
// forever. Claude Code imposes no short workflow timeout (token budget + agent
// cap + async govern instead); background runs pass 0 here and skip the wall cap.
const FOREGROUND_WALL_TIMEOUT_MS = 600_000;
const AGENT_LIFETIME_CAP = 1000;
// Default workflow token budget, matching Claude Code's `task_budget`
// (`{ type: "tokens", total: 128000 }`). The `budget` global meters REAL tokens
// (from each subagent run's usage) against this; scripts self-limit via
// `budget.remaining()`. The hard stop remains the agent() lifetime cap above.
const DEFAULT_TASK_BUDGET_TOKENS = 128_000;
const LOG_LINE_CAP = 1000;
const PARALLEL_DEFAULT_CONCURRENCY = Math.max(2, Math.min(16, (os.cpus()?.length ?? 4) - 2));

// Verbatim from Claude Code 2.1.153 (RunWorkflow). Kept as a module-level
// constant so every workflow subagent fork shares a byte-identical system
// prompt → one warm Anthropic cache entry across every cwd and session.
const WORKFLOW_SUBAGENT_SYSTEM =
	"You are a subagent spawned by a workflow orchestration script. Use the tools available to complete the task.";
// Claude Code 2.1.153 run-id shape: ^wf_[a-z0-9-]{6,}$
const makeRunId = () => `wf_${Date.now().toString(36)}${crypto.randomBytes(3).toString("hex")}`;

// ── StructuredOutput tool-call return (Claude Code 2.1.153 1:1) ──────────────
// CC subagents return structured output by CALLING a tool, not by emitting JSON
// text. We mirror that without busting the subagent cache: a SINGLE
// schema-agnostic `StructuredOutput` tool (byte-identical params every call) is
// registered on the forked child when it reports the matching forkMetadata, and
// the per-call schema is validated script-side. Parent and child share this
// process, so the captured value rides back through this module-level map keyed
// by a callId passed via `forkAgent({ metadata })`.
const STRUCTURED_OUTPUT_TOOL = "StructuredOutput";
const STRUCTURED_OUTPUT_META_KEY = "piWorkflowStructuredOutputCallId";
const structuredOutputCaptures = new Map<string, { captured: boolean; value?: unknown }>();

// ── Journal + resume (CC 2.1.153 resumeFromRunId / phase 4) ─────────────────
// Each agent() result is journaled under a DETERMINISTIC call-path key, so a
// resumed run replays completed steps (no re-fork, no tokens) and only the
// unfinished tail re-executes. Determinism is what makes this sound: workflow
// scripts can't read wall-clock/random, so the same script takes the same path
// and issues the same agent() calls in the same logical positions.
//
// The key is a call PATH, not a flat counter: parallel()/pipeline() namespace
// their children by index (`/pN`, `/sN`) and agent() appends a per-scope ordinal
// (`#N`). Because each child's array index is fixed and calls within a scope are
// sequential, the key is identical across runs regardless of which subagent
// finishes first — the one correctness trap with concurrent parallel tasks.
interface CallScope {
	path: string;
	counter: { n: number };
}
const callScopeStore = new AsyncLocalStorage<CallScope>();

function runDir(cwd: string, runId: string): string {
	return path.join(cwd, ".pi", "workflows", "runs", runId);
}

function appendJournal(cwd: string, runId: string, key: string, result: unknown): void {
	try {
		fs.appendFileSync(path.join(runDir(cwd, runId), "journal.jsonl"), `${JSON.stringify({ key, result })}\n`, {
			mode: 0o600,
		});
	} catch {
		/* best-effort: journaling never blocks a run */
	}
}

// ── Background / async launch (CC async + taskId) ───────────────────────
// A `background` launch runs the workflow detached (subagents driven by a
// workflow-owned AbortController, NOT the launching turn's signal, so they
// survive past the turn) and returns a taskId immediately. Progress/result are
// persisted to runs/<id>/meta.json and polled via `checkRunId`. The registry
// tracks in-flight runs so they can be aborted on session dispose.
interface BackgroundRun {
	controller: AbortController;
	promise: Promise<unknown>;
	startedAt: number;
}
const backgroundRuns = new Map<string, BackgroundRun>();

function readRunStatus(cwd: string, runId: string): { status: string; text: string } {
	const live = backgroundRuns.has(runId);
	let meta: { status?: string; details?: WorkflowDetails; result?: unknown; error?: string } | undefined;
	try {
		meta = JSON.parse(fs.readFileSync(path.join(runDir(cwd, runId), "meta.json"), "utf8"));
	} catch {
		if (!live) return { status: "unknown", text: `No workflow run '${runId}' found.` };
	}
	const status = live && (!meta || meta.status === "running") ? "running" : (meta?.status ?? "running");
	const d = meta?.details;
	const lines = [`Workflow ${runId}: ${status}${d ? ` · ${d.agentCount} agent(s) · ${d.durationMs}ms` : ""}`];
	if (d?.phases?.length) lines.push(`phases: ${d.phases.join(" → ")}`);
	if (meta?.error) lines.push(`error: ${meta.error}`);
	if (status === "completed" && meta?.result !== undefined) {
		const r = meta.result;
		lines.push(`result:\n${typeof r === "string" ? r : JSON.stringify(r, null, 2)}`);
	}
	return { status, text: lines.join("\n") };
}

function loadJournal(cwd: string, runId: string): Map<string, unknown> {
	const replay = new Map<string, unknown>();
	let raw: string;
	try {
		raw = fs.readFileSync(path.join(runDir(cwd, runId), "journal.jsonl"), "utf8");
	} catch {
		return replay;
	}
	for (const line of raw.split("\n")) {
		if (!line.trim()) continue;
		try {
			const entry = JSON.parse(line) as { key: string; result: unknown };
			replay.set(entry.key, entry.result);
		} catch {
			/* skip a torn trailing line */
		}
	}
	return replay;
}

// ── Worktree isolation (CC isolation:"worktree") ────────────────────────
// A subagent launched with { isolation: "worktree" } runs inside a fresh git
// worktree (its own branch off HEAD), so its writes never touch the parent
// checkout. Forked via the core forkAgent({ cwd }) seam; the worktree is removed
// when the subagent settles (success or failure).
interface WorktreeHandle {
	path: string;
	branch: string;
}

function git(cwd: string, args: string[]): string {
	return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
}

function isGitWorkTree(cwd: string): boolean {
	try {
		return git(cwd, ["rev-parse", "--is-inside-work-tree"]) === "true";
	} catch {
		return false;
	}
}

function createWorktree(repoCwd: string, label: string | undefined): WorktreeHandle {
	const id = `${(label ?? "agent").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 24)}-${crypto.randomBytes(4).toString("hex")}`;
	const wtPath = path.join(os.tmpdir(), "pi-workflow-worktrees", id);
	const branch = `pi-wf/${id}`;
	fs.mkdirSync(path.dirname(wtPath), { recursive: true });
	git(repoCwd, ["worktree", "add", "-b", branch, wtPath, "HEAD"]);
	return { path: wtPath, branch };
}

function removeWorktree(repoCwd: string, wt: WorktreeHandle): void {
	try {
		git(repoCwd, ["worktree", "remove", "--force", wt.path]);
	} catch {
		/* best-effort */
	}
	try {
		git(repoCwd, ["branch", "-D", wt.branch]);
	} catch {
		/* best-effort */
	}
}

function structuredOutputInstruction(schema: Record<string, unknown>): string {
	return (
		`\n\nNOTE: You are running inside a workflow script. You MUST return your final answer by calling the \`${STRUCTURED_OUTPUT_TOOL}\` tool; do NOT put your answer in a text response (the script reads ONLY the tool call). If validation fails, read the error and call \`${STRUCTURED_OUTPUT_TOOL}\` again with a corrected shape.` +
		`\nCRITICAL: You MUST call the \`${STRUCTURED_OUTPUT_TOOL}\` tool exactly once to return your final answer as the \`result\` argument, matching this schema:\n${JSON.stringify(schema)}\nAfter calling ${STRUCTURED_OUTPUT_TOOL} successfully, end your turn.`
	);
}

// Surface mirrors Claude Code 2.1.153 `RunWorkflow`. Descriptions are verbatim
// from the binary so the parent model reads identical guidance.
const WorkflowParams = Type.Object({
	script: Type.Optional(
		Type.String({
			description:
				"Self-contained workflow script. Must begin with `export const meta = { name, description, phases }` (pure literal, no computed values) followed by the script body using agent()/parallel()/pipeline()/phase().",
			maxLength: 50_000,
		}),
	),
	name: Type.Optional(
		Type.String({
			description:
				"Name of a predefined workflow (built-in or from .pi/workflows/). Resolves to a self-contained script.",
		}),
	),
	args: Type.Optional(
		Type.Unknown({
			description:
				"Optional input value exposed to the script as the global `args`. Use for parameterized named workflows (e.g. a research question).",
		}),
	),
	scriptPath: Type.Optional(
		Type.String({
			description:
				"Path to a workflow script file on disk. Every Workflow invocation persists its script under the session directory and returns the path in the tool result. To iterate, edit that file with Write/Edit and re-invoke Workflow with the same `scriptPath` instead of re-sending the full script. Takes precedence over `script` and `name`.",
		}),
	),
	resumeFromRunId: Type.Optional(
		Type.String({
			description:
				"Run ID of a prior Workflow invocation to resume from. Completed agent() steps are replayed from the run's journal (no re-fork); only new/unfinished steps run. Determinism-based.",
		}),
	),
	background: Type.Optional(
		Type.Boolean({
			description:
				"Launch the workflow in the background and return a taskId immediately instead of blocking on completion. Use for long fan-outs. Poll progress/result later with `checkRunId`. Subagents keep running past the launching turn.",
		}),
	),
	checkRunId: Type.Optional(
		Type.String({
			description:
				"Return the current status, progress and (if finished) result of a previously launched workflow run (taskId from a `background` launch, or any prior runId). Does not start a new run.",
		}),
	),
});

// disableWorkflows (CC parity): a setting to turn the Workflow tool off. pi
// extensions can't read user settings directly yet, so this uses the idiomatic
// pi toggle — an env var (set once in ~/.profile). When off, nothing is
// registered: no Workflow tool in the prompt/tool list, no /workflows command.
function workflowsDisabled(): boolean {
	const v = (process.env.PI_DISABLE_WORKFLOWS ?? "").trim().toLowerCase();
	return v === "1" || v === "true" || v === "yes" || v === "on";
}

export default function (pi: ExtensionAPI) {
	if (workflowsDisabled()) return;
	// ultracode session mode depends on the Workflow tool (CC gates it on
	// "workflows enabled"), so it is wired here — only when workflows are on.
	wireUltracode(pi);
	// Per-turn `workflow`/`workflows` keyword nudge toward the Workflow tool
	// (CC 2.1.156). Also gated on workflows being enabled, same reason.
	wireWorkflowKeyword(pi);
	// Abort any in-flight background workflow runs when the session goes away.
	pi.onSessionDispose(() => {
		for (const run of backgroundRuns.values()) run.controller.abort();
		backgroundRuns.clear();
	});
	// When THIS extension instance is running inside a workflow subagent fork
	// (forkMetadata carries our callId), register the schema-agnostic
	// StructuredOutput return tool on the child only. Registered post-fork so it
	// is active for the child's turn; never touches the parent's tool list/cache.
	pi.on("session_start", (event) => {
		const callId = (event as { forkMetadata?: Record<string, unknown> }).forkMetadata?.[STRUCTURED_OUTPUT_META_KEY];
		if (typeof callId !== "string" || !structuredOutputCaptures.has(callId)) return;
		pi.registerTool({
			name: STRUCTURED_OUTPUT_TOOL,
			label: STRUCTURED_OUTPUT_TOOL,
			description: "Return your final structured answer to the workflow script. Call exactly once with the `result` argument, then end your turn.",
			parameters: Type.Object({
				result: Type.Unknown({ description: "Your final answer, matching the schema described in the prompt." }),
			}),
			execute: async (_id, params) => {
				const entry = structuredOutputCaptures.get(callId);
				if (entry) {
					entry.value = (params as { result: unknown }).result;
					entry.captured = true;
				}
				return { content: [{ type: "text", text: "Structured answer recorded. End your turn." }], details: {} };
			},
		});
	});

	pi.registerTool({
		name: "Workflow",
		label: "Workflow",
		// Verbatim Claude Code 2.1.153 RunWorkflow description.
		description: "orchestrate subagents with deterministic JavaScript workflow",
		parameters: WorkflowParams,

		async execute(_toolCallId, params, signal, onUpdate, ctx) {
			const input = params as WorkflowInput;

			// Status poll for a prior/background run — no new run.
			if (input.checkRunId) {
				const { text } = readRunStatus(ctx.cwd, input.checkRunId);
				return { content: [{ type: "text", text }], details: {} as unknown as AgentToolDetails };
			}

			const runId = makeRunId();
			const startedAt = Date.now();

			// Resume: re-run the prior run's exact script, replaying journaled agent()
			// results so only the unfinished tail re-forks. Fresh run: empty replay.
			let resolved: { origin: "inline" | "named" | "persisted"; source: string; name?: string; path?: string };
			let replay: Map<string, unknown>;
			if (input.resumeFromRunId) {
				const priorScript = path.join(runDir(ctx.cwd, input.resumeFromRunId), "script.js");
				if (!fs.existsSync(priorScript)) {
					return errorResult(
						`resumeFromRunId: no persisted run '${input.resumeFromRunId}' (expected ${priorScript}).`,
					);
				}
				resolved = { origin: "persisted", source: fs.readFileSync(priorScript, "utf8"), path: priorScript };
				replay = loadJournal(ctx.cwd, input.resumeFromRunId);
			} else {
				const r = resolveSource(input, ctx.cwd);
				if ("error" in r) return errorResult(r.error);
				resolved = r;
				replay = new Map();
			}

			const scriptPath = persistScript(ctx.cwd, runId, resolved.source, {
				origin: resolved.origin,
				name: resolved.name,
				path: resolved.path,
			});
			// Seed the new run's journal with replayed steps so it stays self-contained
			// (a resume of a resume reads one journal, not a chain).
			for (const [key, value] of replay) appendJournal(ctx.cwd, runId, key, value);

			// Deterministic call-path scope for journal keys (see helpers above).
			const rootScope: CallScope = { path: "", counter: { n: 0 } };
			const currentScope = (): CallScope => callScopeStore.getStore() ?? rootScope;
			const nextCallKey = (): string => {
				const scope = currentScope();
				return `${scope.path}#${scope.counter.n++}`;
			};

			const logs: string[] = [];
			const phases: string[] = [];
			const agentCalls: WorkflowAgentCallRecord[] = [];
			let agentCount = 0;

			if (resolved.origin !== "inline") {
				// Surface what we're running so the model can reason about it.
				// Inline scripts log themselves implicitly via the source preview.
			}

			const pushLog = (line: string) => {
				if (logs.length < LOG_LINE_CAP) logs.push(line);
				emitUpdate();
			};

			// Set once the run settles (success/error/timeout) or for background runs.
			// A late progress update — e.g. an in-flight parallel() fork settling after
			// the script already errored/timed out — must NOT call onUpdate: that pushes
			// into a turn that's already closed and crashes the process with
			// "Agent listener invoked outside active run".
			let settled = false;
			const emitUpdate = () => {
				if (!onUpdate || settled) return;
				const partial: WorkflowDetails = {
					runId,
					scriptPath,
					source: "inline",
					phases: [...phases],
					agentCount,
					logs: [...logs],
					agentCalls: [...agentCalls],
					startedAt,
					durationMs: Date.now() - startedAt,
				};
				try {
					onUpdate({
						content: [{ type: "text", text: `Workflow ${runId}${resolved.name ? ` (${resolved.name})` : ""}: ${agentCount} agent(s), ${logs.length} log(s)` }],
						details: partial as unknown as AgentToolDetails,
					});
				} catch {
					// Run already settled; the final tool result carries the details.
				}
			};

			const budgetState = { spent: 0, total: DEFAULT_TASK_BUDGET_TOKENS as number | null };
			// One run-scoped controller drives every subagent fork. Sync runs chain the
			// turn signal so a user abort propagates; background runs swap in a detached
			// controller below so subagents survive past the launching turn. Aborted when
			// the run settles so lingering parallel() forks (after an error/timeout) are
			// cancelled instead of settling later and emitting into a closed turn.
			const runController = new AbortController();
			if (signal) {
				if (signal.aborted) runController.abort();
				else signal.addEventListener("abort", () => runController.abort(), { once: true });
			}
			let runSignal: AbortSignal = runController.signal;
			const globals: SandboxGlobals = {
				args: input.args,
				log: (msg) => pushLog(msg),
				phase: (title) => {
					phases.push(title);
					pushLog(`── ${title} ──`);
				},
				budget: {
					get total() {
						return budgetState.total;
					},
					spent: () => budgetState.spent,
					remaining: () => (budgetState.total === null ? Infinity : Math.max(0, budgetState.total - budgetState.spent)),
				},
				agent: async (prompt, opts = {}) => {
					// Key is assigned synchronously at call entry → deterministic
					// order even for concurrent calls (the array is built in order).
					const key = nextCallKey();
					if (replay.has(key)) {
						agentCalls.push({
							seq: agentCalls.length,
							prompt,
							label: opts.label as string | undefined,
							model: opts.model as string | undefined,
							durationMs: 0,
							resultPreview: "(replayed from journal)",
							status: "replayed",
						});
						pushLog(`↺ replayed ${key}`);
						emitUpdate();
						return replay.get(key) as string | object;
					}
					if (agentCount >= AGENT_LIFETIME_CAP) {
						// Message mirrors Claude Code 2.1.153.
						throw new Error(
							`Workflow agent() call cap reached (${AGENT_LIFETIME_CAP}). This usually means a loop using budget.remaining() never terminates. Add a hard iteration cap to the loop, or pass a token budget.`,
						);
					}
					agentCount++;
					// Live record so the TUI tree shows the subagent as it runs, then
					// flips it to done/error in place when it settles.
					const liveIndex =
						agentCalls.push({
							seq: agentCalls.length,
							prompt,
							label: opts.label as string | undefined,
							model: opts.model as string | undefined,
							durationMs: 0,
							resultPreview: "",
							status: "running",
						}) - 1;
					emitUpdate();
					const result = await runAgent(ctx, prompt, opts, runSignal, (record) => {
						agentCalls[liveIndex] = {
							...record,
							seq: agentCalls[liveIndex].seq,
							status: record.error ? "error" : "done",
						};
						budgetState.spent += record.tokens ?? 0;
						emitUpdate();
					});
					appendJournal(ctx.cwd, runId, key, result);
					return result;
				},
				parallel: async <T>(tasks: Array<() => Promise<T>>) => {
					const parent = currentScope();
					return runParallel(
						tasks.map((task, i) => () =>
							callScopeStore.run({ path: `${parent.path}/p${i}`, counter: { n: 0 } }, task),
						),
						PARALLEL_DEFAULT_CONCURRENCY,
					);
				},
				pipeline: async <T>(stages: Array<() => Promise<T>>) => {
					const parent = currentScope();
					const out: T[] = [];
					for (let i = 0; i < stages.length; i++) {
						out.push(await callScopeStore.run({ path: `${parent.path}/s${i}`, counter: { n: 0 } }, stages[i]));
					}
					return out;
				},
				workflow: async () => {
					throw new Error("Nested workflow() not supported in phase 1. See DESIGN.md phase 5.");
				},
			};

			emitUpdate();

			// Background runs skip the wall cap (governed by the agent cap + session
			// dispose); foreground runs get a generous overall cap.
			const wallTimeoutMs = input.background ? 0 : FOREGROUND_WALL_TIMEOUT_MS;
			const runOnce = async (): Promise<AgentToolResult<AgentToolDetails> & { isError?: boolean }> => {
			try {
				const context = buildSandboxContext(globals);
				const result = await runWorkflowScript(resolved.source, context, {
					syncTimeoutMs: SYNC_TIMEOUT_MS,
					wallTimeoutMs,
					filename: `${runId}.js`,
				});
				const durationMs = Date.now() - startedAt;
				const details: WorkflowDetails = {
					runId,
					scriptPath,
					source: resolved.origin,
					name: resolved.name,
					phases,
					agentCount,
					logs,
					agentCalls,
					startedAt,
					durationMs,
				};
				writeRunMeta(ctx.cwd, runId, { status: "completed", details, result });

				return {
					content: [
						{
							type: "text",
							text: formatCompletion(details, result),
						},
					],
					details: details as unknown as AgentToolDetails,
				};
			} catch (e) {
				const err = e as Error;
				const durationMs = Date.now() - startedAt;
				const details: WorkflowDetails = {
					runId,
					scriptPath,
					source: resolved.origin,
					name: resolved.name,
					phases,
					agentCount,
					logs,
					agentCalls,
					startedAt,
					durationMs,
					error: err.message,
				};
				writeRunMeta(ctx.cwd, runId, { status: "error", details, error: err.message });

				const label = err instanceof DeterminismViolation ? "Determinism violation" : "Workflow error";
				return {
					content: [
						{
							type: "text",
							text: `${label} in ${runId}:\n${err.message}\n\nScript persisted at ${scriptPath} for inspection.`,
						},
					],
					details: details as unknown as AgentToolDetails,
					isError: true,
				};
			} finally {
				// Stop emitting and cancel any still-in-flight forks (e.g. parallel()
				// siblings after one threw, or subagents alive past a wall timeout) so
				// they never settle into a closed turn.
				settled = true;
				runController.abort();
			}
			};

			if (input.background) {
				// Background progress is persisted to meta.json and read via checkRunId;
				// it must never call onUpdate (the launching turn has already returned).
				settled = true;
				const controller = new AbortController();
				runSignal = controller.signal;
				writeRunMeta(ctx.cwd, runId, {
					status: "running",
					details: {
						runId,
						scriptPath,
						source: resolved.origin,
						name: resolved.name,
						phases,
						agentCount,
						logs,
						agentCalls,
						startedAt,
						durationMs: 0,
					},
				});
				const promise = runOnce()
					.catch(() => {})
					.finally(() => backgroundRuns.delete(runId));
				backgroundRuns.set(runId, { controller, promise, startedAt });
				return {
					content: [
						{
							type: "text",
							text: `Workflow ${runId} launched in background${resolved.name ? ` (${resolved.name})` : ""}. Poll with Workflow({ checkRunId: "${runId}" }).`,
						},
					],
					details: {
						runId,
						scriptPath,
						source: resolved.origin,
						name: resolved.name,
						phases: [],
						agentCount: 0,
						logs: [],
						agentCalls: [],
						startedAt,
						durationMs: 0,
					} as unknown as AgentToolDetails,
				};
			}

			return runOnce();
		},

		renderCall(args, theme) {
			const input = args as WorkflowInput;
			if (input.name) {
				return new Text(
					theme.fg("toolTitle", theme.bold("Workflow ")) + theme.fg("accent", input.name),
					0,
					0,
				);
			}
			if (input.scriptPath) {
				return new Text(
					theme.fg("toolTitle", theme.bold("Workflow ")) +
						theme.fg("muted", path.basename(path.dirname(input.scriptPath))),
					0,
					0,
				);
			}
			const code = input.code ?? "";
			const lines = code.split("\n").length;
			const preview = code.slice(0, 80).replace(/\n/g, " ");
			return new Text(
				theme.fg("toolTitle", theme.bold("Workflow ")) +
					theme.fg("accent", `${lines} line${lines === 1 ? "" : "s"}`) +
					"\n  " +
					theme.fg("dim", preview + (code.length > 80 ? "…" : "")),
				0,
				0,
			);
		},

		renderResult(result, _ctx, theme) {
			// see below
			return renderWorkflowResult(result, theme);
		},
	});

	// ──────────────────────────────────────────────────────────────────────────
	// /workflows slash command: lists available workflows by source.

	// Shared by /workflows and the no-arg /workflow: browse → pick → show detail.
	const openWorkflowPicker = async (ctx: any): Promise<void> => {
		const all = discoverWorkflows(ctx.cwd);
		if (all.length === 0) {
			ctx.ui.notify("No workflows discovered. Add scripts to ~/.pi/agent/workflows/ or ./.pi/workflows/.", "info");
			return;
		}

		const groups: Record<string, typeof all> = { builtin: [], user: [], project: [] };
		for (const w of all) groups[w.source].push(w);

		const lines: string[] = [];
		for (const src of ["project", "user", "builtin"] as const) {
			if (groups[src].length === 0) continue;
			lines.push(`--- ${src} (${groups[src].length}) ---`);
			for (const w of groups[src]) {
				lines.push(`${w.name} — ${w.meta.description}`);
			}
		}

		const picked = await ctx.ui.select("Workflows", lines);
		if (!picked || picked.startsWith("---")) return;

		const name = picked.split(" — ")[0];
		const found = all.find((w) => w.name === name);
		if (!found) return;
		ctx.ui.notify(formatWorkflowDetail(found), "info");
	};

	pi.registerCommand("workflows", {
		description: "List available pi-workflow scripts (built-in / user / project)",
		handler: async (_args, ctx) => openWorkflowPicker(ctx),
	});

	// /workflow (singular): direct detail, scaffold-new, or browse (reuses picker).
	wireWorkflowCommand(pi, openWorkflowPicker);
}

const AGENT_TREE_CAP = 12;

function agentStatusIcon(rec: WorkflowAgentCallRecord, theme: any): string {
	switch (rec.status) {
		case "running":
			return theme.fg("accent", "●");
		case "error":
			return theme.fg("error", "✗");
		case "replayed":
			return theme.fg("muted", "↻");
		default:
			return rec.error ? theme.fg("error", "✗") : theme.fg("success", "✓");
	}
}

function agentTreeLabel(rec: WorkflowAgentCallRecord): string {
	const base = (rec.label ?? rec.prompt).replace(/\s+/g, " ").trim();
	return base.length > 48 ? `${base.slice(0, 47)}…` : base;
}

// Live progress tree: one line per subagent with status icon, label, model and
// duration (or "running…"). Capped so a fan-out of hundreds stays readable.
function agentTreeLines(details: WorkflowDetails, theme: any): string[] {
	const calls = details.agentCalls;
	const lines: string[] = [];
	let shown = calls;
	if (calls.length > AGENT_TREE_CAP) {
		lines.push(`  ${theme.fg("muted", `… ${calls.length - AGENT_TREE_CAP} earlier agent(s)`)}`);
		shown = calls.slice(-AGENT_TREE_CAP);
	}
	shown.forEach((rec, i) => {
		const branch = theme.fg("dim", i === shown.length - 1 ? "└─" : "├─");
		const model = rec.model ? theme.fg("dim", ` ${rec.model}`) : "";
		const meta =
			rec.status === "running"
				? theme.fg("muted", " running…")
				: theme.fg("muted", ` ${rec.durationMs}ms`);
		lines.push(`  ${branch} ${agentStatusIcon(rec, theme)} ${agentTreeLabel(rec)}${model}${meta}`);
	});
	return lines;
}

function renderWorkflowResult(result: any, theme: any): any {
	const details = result.details as unknown as WorkflowDetails | undefined;
	if (!details) {
		const t = result.content[0];
		return new Text(t?.type === "text" ? t.text : "(no output)", 0, 0);
	}
	const running = details.agentCalls.some((rec) => rec.status === "running");
	const icon = details.error
		? theme.fg("error", "✗")
		: running
			? theme.fg("accent", "●")
			: theme.fg("success", "✓");
	const label = details.name ? `${details.runId} (${details.name})` : details.runId;
	const head =
		icon +
		" " +
		theme.fg("toolTitle", theme.bold("Workflow ")) +
		theme.fg("accent", label) +
		theme.fg(
			"muted",
			` · ${details.agentCount} agent${details.agentCount === 1 ? "" : "s"} · ${details.durationMs}ms`,
		);
	const phasesLine = details.phases.length
		? `\n  ${theme.fg("muted", "phases:")} ${details.phases.join(" → ")}`
		: "";
	const err = details.error ? `\n  ${theme.fg("error", details.error)}` : "";
	return new Text([head + phasesLine + err, ...agentTreeLines(details, theme)].join("\n"), 0, 0);
}

// ──────────────────────────────────────────────────────────────────────────────
// Internals

function errorResult(message: string) {
	return {
		content: [{ type: "text" as const, text: message }],
		isError: true,
	};
}

function persistScript(
	cwd: string,
	runId: string,
	source: string,
	origin?: { origin: "inline" | "named" | "persisted"; name?: string; path?: string },
): string {
	const dir = path.join(cwd, ".pi", "workflows", "runs", runId);
	fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
	const scriptPath = path.join(dir, "script.js");
	fs.writeFileSync(scriptPath, source, { mode: 0o600 });
	if (origin && origin.origin !== "inline") {
		try {
			fs.writeFileSync(
				path.join(dir, "origin.json"),
				JSON.stringify({ origin: origin.origin, name: origin.name, path: origin.path }, null, 2),
				{ mode: 0o600 },
			);
		} catch {
			/* best-effort */
		}
	}
	return scriptPath;
}

/**
 * Resolve the workflow source from a tool input: inline `code`, named lookup,
 * or persisted scriptPath. Returns either the resolved source bundle or an
 * error message ready for surface back to the model.
 */
function resolveSource(
	input: WorkflowInput,
	cwd: string,
):
	| { origin: "inline" | "named" | "persisted"; source: string; name?: string; path?: string }
	| { error: string } {
	const scriptSource = input.script ?? input.code; // `code` is the legacy 2.1.146 alias
	const supplied = [scriptSource ? "script" : null, input.name ? "name" : null, input.scriptPath ? "scriptPath" : null].filter(
		(k): k is string => Boolean(k),
	);
	if (supplied.length === 0) {
		// Verbatim Claude Code 2.1.153 validation message.
		return { error: "Must provide script, name, or scriptPath" };
	}
	if (supplied.length > 1) {
		return { error: `Pass exactly one of script/name/scriptPath, got: ${supplied.join(", ")}.` };
	}
	if (scriptSource) {
		const metaErr = requireMetaHeader(scriptSource);
		if (metaErr) return { error: metaErr };
		return { origin: "inline", source: scriptSource };
	}
	if (input.name) {
		const hit = findWorkflowByName(cwd, input.name);
		if (!hit) {
			const all = discoverWorkflows(cwd);
			const available = all.map((w) => `${w.name} (${w.source})`).join(", ") || "(none)";
			return { error: `Workflow '${input.name}' not found. Available: ${available}.` };
		}
		try {
			return { origin: "named", source: loadWorkflowSource(hit.path), name: hit.name, path: hit.path };
		} catch (e) {
			return { error: `Failed to load workflow '${input.name}' from ${hit.path}: ${(e as Error).message}` };
		}
	}
	if (input.scriptPath) {
		if (!fs.existsSync(input.scriptPath)) {
			return { error: `scriptPath does not exist: ${input.scriptPath}` };
		}
		try {
			return { origin: "persisted", source: loadWorkflowSource(input.scriptPath), path: input.scriptPath };
		} catch (e) {
			return { error: `Failed to read scriptPath ${input.scriptPath}: ${(e as Error).message}` };
		}
	}
	return { error: "Unreachable: no source resolved." };
}

function writeRunMeta(
	cwd: string,
	runId: string,
	body: Record<string, unknown>,
): void {
	const dir = path.join(cwd, ".pi", "workflows", "runs", runId);
	try {
		fs.writeFileSync(path.join(dir, "meta.json"), JSON.stringify(body, null, 2), { mode: 0o600 });
	} catch {
		/* best-effort */
	}
}

async function runAgent(
	ctx: ExtensionContext,
	prompt: string,
	opts: Record<string, unknown>,
	parentSignal: AbortSignal | undefined,
	onComplete: (record: WorkflowAgentCallRecord) => void,
): Promise<string | object> {
	const t0 = Date.now();
	const label = typeof opts.label === "string" ? opts.label : undefined;
	const model = typeof opts.model === "string" ? opts.model : undefined;
	const agentType = typeof opts.agentType === "string" ? opts.agentType : undefined;
	const allowedTools = Array.isArray(opts.allowedTools) ? (opts.allowedTools as string[]) : undefined;
	const schema = isObject(opts.schema) ? opts.schema : undefined;

	// Structured output rides back via the StructuredOutput tool call (CC 1:1).
	// Seed a rendezvous slot the child's tool writes into; correlate via metadata.
	const structuredCallId = schema ? `so_${crypto.randomBytes(8).toString("hex")}` : undefined;
	if (structuredCallId) structuredOutputCaptures.set(structuredCallId, { captured: false });

	const subagentPrompt = schema ? `${prompt}${structuredOutputInstruction(schema)}` : prompt;

	// Optional git-worktree isolation: the subagent runs in a throwaway worktree
	// off HEAD, removed when it settles. Requires a git working tree.
	let worktree: WorktreeHandle | undefined;
	if (opts.isolation === "worktree") {
		if (!isGitWorkTree(ctx.cwd)) {
			throw new Error('agent({ isolation: "worktree" }) requires the workflow cwd to be a git working tree.');
		}
		worktree = createWorktree(ctx.cwd, label);
	}

	// Cache-stability (see pi-cache-stability skill): the subagent prefix is the
	// byte-identical WORKFLOW_SUBAGENT_SYSTEM + tool schemas. `context: "none"`
	// drops the parent's mutable auto-built prompt (cwd/date/skills/transcript),
	// so every workflow subagent across every session/cwd shares one warm cache
	// entry. Per-call dynamic data lives in the user `prompt`. This also matches
	// Claude Code 2.1.153, whose workflow-subagent uses exactly this system
	// prompt with no parent context.
	//
	// When the caller routes a named agent type (e.g. agent({ agent: "explore" })),
	// hand the child to that definition instead: drop the forced system prompt so
	// the executor applies the agent's own stable append + tools + model (cheap
	// read-only explore vs. the default general/opus child). Stable agents
	// (cacheProfile: "stable") keep a warm per-type cache entry under context:"none".
	const { handle } = await ctx.forkAgent({
		prompt: subagentPrompt,
		agentType,
		systemPrompt: agentType ? undefined : WORKFLOW_SUBAGENT_SYSTEM,
		context: "none",
		allowedTools,
		model,
		signal: parentSignal,
		description: label ?? "workflow-subagent",
		silent: true,
		// Lets this extension, running inside the child, recognise the fork and
		// register the StructuredOutput return tool for this specific call.
		metadata: structuredCallId ? { [STRUCTURED_OUTPUT_META_KEY]: structuredCallId } : undefined,
		// Isolation: run the subagent inside the throwaway worktree (core seam).
		cwd: worktree?.path,
	});

	try {
		const details = await handle.wait();
		const text = extractFinalText(details);
		const durationMs = Date.now() - t0;
		const record: WorkflowAgentCallRecord = {
			seq: -1,
			prompt,
			label,
			model,
			durationMs,
			resultPreview: text.slice(0, 200),
			tokens: (details.runs?.[0]?.usage as { totalTokens?: number } | undefined)?.totalTokens ?? 0,
		};
		onComplete(record);
		if (schema) {
			const entry = structuredCallId ? structuredOutputCaptures.get(structuredCallId) : undefined;
			if (structuredCallId) structuredOutputCaptures.delete(structuredCallId);
			if (entry?.captured) return entry.value as object;
			// Fallback for a subagent that answered in text instead of calling the
			// tool (e.g. an older model): keep the prior JSON-from-text behaviour.
			try {
				return JSON.parse(text);
			} catch {
				throw new Error(
					`Subagent did not return structured output via ${STRUCTURED_OUTPUT_TOOL} or valid JSON. Got: ${text.slice(0, 400)}`,
				);
			}
		}
		return text;
	} catch (e) {
		if (structuredCallId) structuredOutputCaptures.delete(structuredCallId);
		const err = e as Error;
		const durationMs = Date.now() - t0;
		const record: WorkflowAgentCallRecord = {
			seq: -1,
			prompt,
			label,
			model,
			durationMs,
			resultPreview: "",
			error: err.message,
		};
		onComplete(record);
		throw err;
	} finally {
		if (worktree) removeWorktree(ctx.cwd, worktree);
	}
}

function extractFinalText(details: AgentToolDetails): string {
	// AgentToolDetails.runs[] contains AgentRunDetails with finalOutput/rawOutput.
	// For a single forked agent there's exactly one run.
	const run = details.runs?.[0];
	if (!run) return "";
	if (run.error) throw new Error(`Subagent failed: ${run.error}`);
	return run.finalOutput ?? run.rawOutput ?? "";
}

async function runParallel<T>(tasks: Array<() => Promise<T>>, concurrency: number): Promise<T[]> {
	if (tasks.length === 0) return [];
	const limit = Math.max(1, Math.min(concurrency, tasks.length));
	const results: T[] = new Array(tasks.length);
	let nextIndex = 0;
	const workers = new Array(limit).fill(null).map(async () => {
		while (true) {
			const i = nextIndex++;
			if (i >= tasks.length) return;
			results[i] = await tasks[i]();
		}
	});
	await Promise.all(workers);
	return results;
}

function formatCompletion(details: WorkflowDetails, result: unknown): string {
	const head = `Workflow ${details.runId} completed in ${details.durationMs}ms (${details.agentCount} agent${details.agentCount === 1 ? "" : "s"}).`;
	const phases = details.phases.length ? `\nPhases: ${details.phases.join(" → ")}` : "";
	const logTail = details.logs.length ? `\n\nLast ${Math.min(5, details.logs.length)} log lines:\n${details.logs.slice(-5).map((l) => `  ${l}`).join("\n")}` : "";
	const resultStr =
		result === undefined
			? ""
			: typeof result === "string"
				? `\n\nResult:\n${result}`
				: `\n\nResult:\n${JSON.stringify(result, null, 2)}`;
	return `${head}${phases}${logTail}${resultStr}\n\nScript: ${details.scriptPath}`;
}

function isObject(v: unknown): v is Record<string, unknown> {
	return v !== null && typeof v === "object" && !Array.isArray(v);
}

/**
 * Claude Code 2.1.153 requires every workflow script (inline or named) to begin
 * with a pure-literal `export const meta = {...}` header. We allow leading
 * comments/whitespace before the export. Returns an error string or null.
 */
function requireMetaHeader(source: string): string | null {
	const withoutLeading = source.replace(/^(?:\s|\/\/[^\n]*\n|\/\*[\s\S]*?\*\/)*/, "");
	if (/^export\s+const\s+meta\s*=\s*\{/.test(withoutLeading)) return null;
	return "Script must begin with `export const meta = { name, description, phases }` (pure literal).";
}

