/**
 * agent({ agent: "explore" }) routes a named agent type through forkAgent.
 *
 * The workflow agent() call captures a subagent-type field and forwards it as
 * forkAgent({ agentType }), letting the fork's executor resolve that agent
 * definition's tools/model/prompt (e.g. cheap read-only explore) instead of the
 * default general child. When a type is set we also drop the forced
 * WORKFLOW_SUBAGENT_SYSTEM so the agent definition's own stable prompt drives.
 *
 * Run: node test/agent-type.test.mjs
 */

import assert from "node:assert/strict";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const register = await jiti.import("../src/index.ts", { default: true });

function mockPi() {
	const tools = {};
	const pi = { registerTool: (d) => { tools[d.name] = d; }, on: () => {}, onSessionDispose: () => {}, registerCommand: () => {} };
	return { pi, tools };
}

function ctxCapturing(captured) {
	return {
		cwd: process.cwd(),
		forkAgent: async (opts) => {
			captured.opts = opts;
			return { sessionId: "s", handle: { status: "completed", wait: async () => ({ runs: [{ status: "completed", finalOutput: "ok" }] }) } };
		},
	};
}

async function runScript(script, captured) {
	const { pi, tools } = mockPi();
	register(pi);
	const res = await tools.Workflow.execute("t", { script }, undefined, undefined, ctxCapturing(captured));
	assert.ok(!res.isError, `workflow should complete: ${res.content?.[0]?.text}`);
	return res;
}

const tests = [];
const test = (name, fn) => tests.push({ name, fn });

test("object form agent({ agent: 'explore' }) forwards agentType and drops the forced system prompt", async () => {
	const captured = {};
	await runScript(
		`export const meta = { name: "t", description: "d", phases: [] };
return await agent({ agent: "explore", task: "find the retry logic" });`,
		captured,
	);
	assert.equal(captured.opts.agentType, "explore", "agentType routed to forkAgent");
	assert.equal(captured.opts.systemPrompt, undefined, "agent-typed fork lets the definition prompt drive");
});

test("string+opts form agent('prompt', { agent: 'explore' }) also routes agentType", async () => {
	const captured = {};
	await runScript(
		`export const meta = { name: "t", description: "d", phases: [] };
return await agent("find the retry logic", { agent: "explore" });`,
		captured,
	);
	assert.equal(captured.opts.agentType, "explore", "string-prompt form routes agentType too");
	assert.equal(captured.opts.systemPrompt, undefined);
});

test("untyped agent() keeps the default general child + WORKFLOW_SUBAGENT_SYSTEM", async () => {
	const captured = {};
	await runScript(
		`export const meta = { name: "t", description: "d", phases: [] };
return await agent("do some work");`,
		captured,
	);
	assert.equal(captured.opts.agentType, undefined, "no agent type by default");
	assert.equal(typeof captured.opts.systemPrompt, "string", "default fork keeps the workflow system prompt");
	assert.ok(captured.opts.systemPrompt.length > 0, "system prompt is non-empty");
});

let failed = 0;
for (const { name, fn } of tests) {
	try { await fn(); console.log(`  ✓ ${name}`); }
	catch (e) { failed++; console.error(`  ✗ ${name}\n    ${e.stack ?? e.message}`); }
}
console.log(`${tests.length - failed}/${tests.length} passed`);
if (failed > 0) process.exit(1);

