37		full:
38			"Ultracode is on: optimize for the most exhaustive, correct answer \u2014 not the " +
39			"fastest or cheapest. Use the Workflow tool on every substantive task; token cost " +
40			"is not a constraint. Solo only on conversational or trivial turns.",
41		sparse: "Ultracode is still on \u2014 use the Workflow tool on substantive tasks; exhaustive correctness over speed or cost.",
42		off: "Ultracode is off \u2014 the Workflow tool's standard opt-in rule applies again.",
43	} as const;
