47	export interface UltracodeState {
48		enabled: boolean;
49		/** Turns since the last reminder was emitted (drives the sparse cadence). */
50		turnsSinceReminder: number;
51		/** Emit the full reminder on the next turn (set when enabled). */
52		pendingFull: boolean;
53		/** Emit the off reminder once on the next turn (set when disabled). */
54		pendingOff: boolean;
55	}
56	
57	export function initialState(): UltracodeState {
58		return { enabled: false, turnsSinceReminder: 0, pendingFull: false, pendingOff: false };
59	}
60	
