72		if (state.pendingOff) {
73			return { reminder: "off", state: { ...state, pendingOff: false } };
74		}
75		if (!state.enabled) return { reminder: null, state };
76		if (state.pendingFull) {
77			return { reminder: "full", state: { ...state, pendingFull: false, turnsSinceReminder: 0 } };
78		}
79		const turns = state.turnsSinceReminder + 1;
80		if (turns >= SPARSE_EVERY) {
81			return { reminder: "sparse", state: { ...state, turnsSinceReminder: 0 } };
82		}
83		return { reminder: null, state: { ...state, turnsSinceReminder: turns } };
84	}
85	
86	/** Parse `/ultracode [on|off]` (no arg = toggle). */
87	export function parseToggle(args: string, currentlyEnabled: boolean): boolean {
88		const a = args.trim().toLowerCase();
89		if (a === "on" || a === "enable") return true;
90		if (a === "off" || a === "disable") return false;
91		return !currentlyEnabled;
92	}
93	
94	export function reminderText(reminder: Reminder): string {
95		return REMINDERS[reminder];
96	}
97	
98	/**
99	 * Wire the ultracode command + per-turn reminder onto a pi instance. Call this
100	 * only when the Workflow tool is registered (workflows enabled).
101	 */
102	export function wireUltracode(pi: ExtensionAPI): void {
103		let state = initialState();
104		let priorLevel: ThinkingLevel | null = null;
