116					pi.setThinkingLevel(ULTRACODE_LEVEL);
117					state = enable(state);
118					ctx.ui.notify(`Ultracode on \u2014 effort set to ${ULTRACODE_LEVEL}, exhaustive mode.`, "info");
119				} else {
