124				}
125			},
126		});
127	
128		pi.on("before_agent_start", () => {
129			const { reminder, state: next } = planTurn(state);
130			state = next;
131			if (!reminder) return;
132			return {
133				message: {
134					customType: "ultracode",
135					content: REMINDERS[reminder],
136					display: false,
137				},
138			};
139		});
140	}
