1	/**
2	 * Standalone sandbox smoke tests.
3	 *
4	 * Verifies determinism shims, allowed globals, and script-evaluation
5	 * mechanics without booting pi or calling forkAgent. agent() is stubbed
6	 * so we only test the sandbox & wiring.
7	 *
8	 * Run: node --import tsx test/sandbox.test.mjs
9	 *      (or any TS loader that handles .ts imports)
10	 */
11	
12	import assert from "node:assert/strict";
13	
14	// Use jiti to load the .ts modules from source
15	import { createJiti } from "jiti";
16	const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
17	const { buildSandboxContext, runWorkflowScript, DeterminismViolation } = await jiti.import("../src/sandbox.ts");
18	
19	const tests = [];
20	const test = (name, fn) => tests.push({ name, fn });
21	
22	const stubGlobals = (over = {}) => ({
23		args: undefined,
24		log: () => {},
25		phase: () => {},
26		budget: { total: null, spent: () => 0, remaining: () => Infinity },
27		agent: async () => "stubbed",
28		parallel: async (tasks) => Promise.all(tasks.map((t) => t())),
29		pipeline: async (stages) => {
30			const r = [];
31			for (const s of stages) r.push(await s());
32			return r;
33		},
34		workflow: async () => {
35			throw new Error("not impl");
36		},
37		...over,
38	});
39	
40	// ---------------------------------------------------------------------------
41	
42	test("script returns a value", async () => {
43		const ctx = buildSandboxContext(stubGlobals());
44		const r = await runWorkflowScript("return 2 + 3", ctx, { syncTimeoutMs: 5000, filename: "t1.js" });
45		assert.equal(r, 5);
46	});
47	
48	test("args global is exposed", async () => {
49		const ctx = buildSandboxContext(stubGlobals({ args: { name: "Luke" } }));
50		const r = await runWorkflowScript("return args.name", ctx, { syncTimeoutMs: 5000, filename: "t2.js" });
51		assert.equal(r, "Luke");
52	});
53	
54	test("agent() is awaitable and returns the stub", async () => {
55		const calls = [];
56		const ctx = buildSandboxContext(
57			stubGlobals({
58				agent: async (prompt, opts) => {
59					calls.push({ prompt, opts });
60					return `OK: ${prompt}`;
61				},
62			}),
63		);
64		const r = await runWorkflowScript(
65			`const a = await agent("hello", { label: "greet" }); return a;`,
66			ctx,
67			{ syncTimeoutMs: 5000, filename: "t3.js" },
68		);
69		assert.equal(r, "OK: hello");
70		assert.equal(calls.length, 1);
71		assert.equal(calls[0].opts.label, "greet");
72	});
73	
74	test("agent() rejects an empty prompt with an actionable message", async () => {
75		const ctx = buildSandboxContext(stubGlobals());
76		await assert.rejects(
77			runWorkflowScript('return await agent("");', ctx, { syncTimeoutMs: 5000, filename: "empty.js" }),
78			/non-empty prompt/,
79		);
80	});
81	
82	test("a floating rejecting agent() call does not crash the host", async () => {
83		// Reproduces the crash that exited pi: a non-awaited agent() whose underlying
84		// forkAgent rejects. The boundary guard must swallow the floating rejection.
85		let unhandled = null;
86		const onUnhandled = (e) => {
87			unhandled = e;
88		};
89		process.on("unhandledRejection", onUnhandled);
90		try {
91			const ctx = buildSandboxContext(
92				stubGlobals({
93					agent: async () => {
94						throw new Error("forkAgent requires a non-empty prompt");
95					},
96				}),
97			);
98			const r = await runWorkflowScript('agent("do thing"); return "ok";', ctx, {
99				syncTimeoutMs: 5000,
100				filename: "float.js",
101			});
102			assert.equal(r, "ok");
103			// Let any pending rejection surface on the microtask/timer queue.
104			await new Promise((res) => setTimeout(res, 10));
105			assert.equal(unhandled, null, "floating agent() rejection must be swallowed, not crash the host");
106		} finally {
107			process.off("unhandledRejection", onUnhandled);
108		}
109	});
110	
111	test("agent() accepts the Agent-tool object shape ({ task, description, extraContext })", async () => {
112		let seen;
113		const ctx = buildSandboxContext(
114			stubGlobals({
115				agent: async (prompt, opts) => {
116					seen = { prompt, opts };
117					return "ok";
118				},
119			}),
120		);
121		const r = await runWorkflowScript(
122			`return await agent({ task: "do X", description: "my label", extraContext: "Breadth: medium", model: "haiku", agent: "explore" });`,
123			ctx,
124			{ syncTimeoutMs: 5000, filename: "obj.js" },
125		);
126		assert.equal(r, "ok");
127		assert.equal(seen.prompt, "do X\n\nBreadth: medium");
128		assert.equal(seen.opts.label, "my label");
129		assert.equal(seen.opts.model, "haiku");
130		assert.equal(seen.opts.agentType, "explore"); // captured for the future fork-by-agent seam
131	});
132	
133	test("parallel() rejects promises (non-thunks) with an actionable error, not a cryptic apply error", async () => {
134		const ctx = buildSandboxContext(stubGlobals());
135		await assert.rejects(
136			runWorkflowScript('return await parallel([agent("a"), agent("b")]);', ctx, {
137				syncTimeoutMs: 5000,
138				filename: "promises.js",
139			}),
140			(e) => /thunks/.test(e.message) && /Item 0 is a Promise/.test(e.message),
141		);
142	});
143	
144	test("pipeline() rejects non-thunks too", async () => {
145		const ctx = buildSandboxContext(stubGlobals());
146		await assert.rejects(
147			runWorkflowScript('return await pipeline([Promise.resolve(1)]);', ctx, {
148				syncTimeoutMs: 5000,
149				filename: "pipe.js",
150			}),
151			/thunks/,
152		);
153	});
154	
155	test("log() collects messages", async () => {
156		const lines = [];
157		const ctx = buildSandboxContext(stubGlobals({ log: (m) => lines.push(m) }));
158		await runWorkflowScript(`log("one"); log("two"); return null;`, ctx, { syncTimeoutMs: 5000, filename: "t4.js" });
159		assert.deepEqual(lines, ["one", "two"]);
160	});
161	
162	test("phase() collects titles", async () => {
163		const phases = [];
164		const ctx = buildSandboxContext(stubGlobals({ phase: (t) => phases.push(t) }));
165		await runWorkflowScript(`phase("Plan"); phase("Build"); return null;`, ctx, { syncTimeoutMs: 5000, filename: "t5.js" });
166		assert.deepEqual(phases, ["Plan", "Build"]);
167	});
168	
169	test("Date.now() throws DeterminismViolation", async () => {
170		const ctx = buildSandboxContext(stubGlobals());
171		await assert.rejects(
172			runWorkflowScript("return Date.now()", ctx, { syncTimeoutMs: 5000, filename: "t6.js" }),
173			(e) => e.message.includes("Date.now") && e.message.includes("breaks resume"),
174		);
175	});
176	
177	test("new Date() throws DeterminismViolation", async () => {
178		const ctx = buildSandboxContext(stubGlobals());
179		await assert.rejects(
180			runWorkflowScript("return new Date().toISOString()", ctx, { syncTimeoutMs: 5000, filename: "t7.js" }),
181			/Date.*breaks resume/,
182		);
183	});
184	
185	test("Math.random() throws", async () => {
186		const ctx = buildSandboxContext(stubGlobals());
187		await assert.rejects(
188			runWorkflowScript("return Math.random()", ctx, { syncTimeoutMs: 5000, filename: "t8.js" }),
189			/Math\.random/,
190		);
191	});
192	
193	test("Math.floor() still works (allowed)", async () => {
194		const ctx = buildSandboxContext(stubGlobals());
195		const r = await runWorkflowScript("return Math.floor(3.7)", ctx, { syncTimeoutMs: 5000, filename: "t9.js" });
196		assert.equal(r, 3);
197	});
198	
199	test("setTimeout throws", async () => {
200		const ctx = buildSandboxContext(stubGlobals());
201		await assert.rejects(
202			runWorkflowScript("setTimeout(() => {}, 100); return 1;", ctx, { syncTimeoutMs: 5000, filename: "t10.js" }),
203			/setTimeout/,
204		);
205	});
206	
207	test("import statement is rejected at parse time", async () => {
208		const ctx = buildSandboxContext(stubGlobals());
209		await assert.rejects(
210			runWorkflowScript('import fs from "node:fs"', ctx, { syncTimeoutMs: 5000, filename: "t11.js" }),
211			/cannot use `import`/,
212		);
213	});
214	
215	test("export const meta is rewritten to globalThis.__meta", async () => {
216		const ctx = buildSandboxContext(stubGlobals());
217		await runWorkflowScript(
218			`export const meta = { name: "test", description: "x" };\nreturn globalThis.__meta;`,
219			ctx,
220			{ syncTimeoutMs: 5000, filename: "t12.js" },
221		);
222		// Just verifying it parses; we tossed the result.
223	});
224	
225	test("parallel runs all tasks", async () => {
226		const ctx = buildSandboxContext(stubGlobals());
227		const r = await runWorkflowScript(
228			`return await parallel([
229				() => Promise.resolve(1),
230				() => Promise.resolve(2),
231				() => Promise.resolve(3),
