/**
 * Standalone sandbox smoke tests.
 *
 * Verifies determinism shims, allowed globals, and script-evaluation
 * mechanics without booting pi or calling forkAgent. agent() is stubbed
 * so we only test the sandbox & wiring.
 *
 * Run: node --import tsx test/sandbox.test.mjs
 *      (or any TS loader that handles .ts imports)
 */

import assert from "node:assert/strict";

// Use jiti to load the .ts modules from source
import { createJiti } from "jiti";
const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const { buildSandboxContext, runWorkflowScript, DeterminismViolation } = await jiti.import("../src/sandbox.ts");

const tests = [];
const test = (name, fn) => tests.push({ name, fn });

const stubGlobals = (over = {}) => ({
	args: undefined,
	log: () => {},
	phase: () => {},
	budget: { total: null, spent: () => 0, remaining: () => Infinity },
	agent: async () => "stubbed",
	parallel: async (tasks) => Promise.all(tasks.map((t) => t())),
	pipeline: async (stages) => {
		const r = [];
		for (const s of stages) r.push(await s());
		return r;
	},
	workflow: async () => {
		throw new Error("not impl");
	},
	...over,
});

// ---------------------------------------------------------------------------

test("script returns a value", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	const r = await runWorkflowScript("return 2 + 3", ctx, { syncTimeoutMs: 5000, filename: "t1.js" });
	assert.equal(r, 5);
});

test("args global is exposed", async () => {
	const ctx = buildSandboxContext(stubGlobals({ args: { name: "Luke" } }));
	const r = await runWorkflowScript("return args.name", ctx, { syncTimeoutMs: 5000, filename: "t2.js" });
	assert.equal(r, "Luke");
});

test("agent() is awaitable and returns the stub", async () => {
	const calls = [];
	const ctx = buildSandboxContext(
		stubGlobals({
			agent: async (prompt, opts) => {
				calls.push({ prompt, opts });
				return `OK: ${prompt}`;
			},
		}),
	);
	const r = await runWorkflowScript(
		`const a = await agent("hello", { label: "greet" }); return a;`,
		ctx,
		{ syncTimeoutMs: 5000, filename: "t3.js" },
	);
	assert.equal(r, "OK: hello");
	assert.equal(calls.length, 1);
	assert.equal(calls[0].opts.label, "greet");
});

test("agent() rejects an empty prompt with an actionable message", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript('return await agent("");', ctx, { syncTimeoutMs: 5000, filename: "empty.js" }),
		/non-empty prompt/,
	);
});

test("a floating rejecting agent() call does not crash the host", async () => {
	// Reproduces the crash that exited pi: a non-awaited agent() whose underlying
	// forkAgent rejects. The boundary guard must swallow the floating rejection.
	let unhandled = null;
	const onUnhandled = (e) => {
		unhandled = e;
	};
	process.on("unhandledRejection", onUnhandled);
	try {
		const ctx = buildSandboxContext(
			stubGlobals({
				agent: async () => {
					throw new Error("forkAgent requires a non-empty prompt");
				},
			}),
		);
		const r = await runWorkflowScript('agent("do thing"); return "ok";', ctx, {
			syncTimeoutMs: 5000,
			filename: "float.js",
		});
		assert.equal(r, "ok");
		// Let any pending rejection surface on the microtask/timer queue.
		await new Promise((res) => setTimeout(res, 10));
		assert.equal(unhandled, null, "floating agent() rejection must be swallowed, not crash the host");
	} finally {
		process.off("unhandledRejection", onUnhandled);
	}
});

test("agent() accepts the Agent-tool object shape ({ task, description, extraContext })", async () => {
	let seen;
	const ctx = buildSandboxContext(
		stubGlobals({
			agent: async (prompt, opts) => {
				seen = { prompt, opts };
				return "ok";
			},
		}),
	);
	const r = await runWorkflowScript(
		`return await agent({ task: "do X", description: "my label", extraContext: "Breadth: medium", model: "haiku", agent: "explore" });`,
		ctx,
		{ syncTimeoutMs: 5000, filename: "obj.js" },
	);
	assert.equal(r, "ok");
	assert.equal(seen.prompt, "do X\n\nBreadth: medium");
	assert.equal(seen.opts.label, "my label");
	assert.equal(seen.opts.model, "haiku");
	assert.equal(seen.opts.agentType, "explore"); // captured for the future fork-by-agent seam
});

test("parallel() rejects promises (non-thunks) with an actionable error, not a cryptic apply error", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript('return await parallel([agent("a"), agent("b")]);', ctx, {
			syncTimeoutMs: 5000,
			filename: "promises.js",
		}),
		(e) => /thunks/.test(e.message) && /Item 0 is a Promise/.test(e.message),
	);
});

test("pipeline() rejects non-thunks too", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript('return await pipeline([Promise.resolve(1)]);', ctx, {
			syncTimeoutMs: 5000,
			filename: "pipe.js",
		}),
		/thunks/,
	);
});

test("log() collects messages", async () => {
	const lines = [];
	const ctx = buildSandboxContext(stubGlobals({ log: (m) => lines.push(m) }));
	await runWorkflowScript(`log("one"); log("two"); return null;`, ctx, { syncTimeoutMs: 5000, filename: "t4.js" });
	assert.deepEqual(lines, ["one", "two"]);
});

test("phase() collects titles", async () => {
	const phases = [];
	const ctx = buildSandboxContext(stubGlobals({ phase: (t) => phases.push(t) }));
	await runWorkflowScript(`phase("Plan"); phase("Build"); return null;`, ctx, { syncTimeoutMs: 5000, filename: "t5.js" });
	assert.deepEqual(phases, ["Plan", "Build"]);
});

test("Date.now() throws DeterminismViolation", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript("return Date.now()", ctx, { syncTimeoutMs: 5000, filename: "t6.js" }),
		(e) => e.message.includes("Date.now") && e.message.includes("breaks resume"),
	);
});

test("new Date() throws DeterminismViolation", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript("return new Date().toISOString()", ctx, { syncTimeoutMs: 5000, filename: "t7.js" }),
		/Date.*breaks resume/,
	);
});

test("Math.random() throws", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript("return Math.random()", ctx, { syncTimeoutMs: 5000, filename: "t8.js" }),
		/Math\.random/,
	);
});

test("Math.floor() still works (allowed)", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	const r = await runWorkflowScript("return Math.floor(3.7)", ctx, { syncTimeoutMs: 5000, filename: "t9.js" });
	assert.equal(r, 3);
});

test("setTimeout throws", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript("setTimeout(() => {}, 100); return 1;", ctx, { syncTimeoutMs: 5000, filename: "t10.js" }),
		/setTimeout/,
	);
});

test("import statement is rejected at parse time", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript('import fs from "node:fs"', ctx, { syncTimeoutMs: 5000, filename: "t11.js" }),
		/cannot use `import`/,
	);
});

test("export const meta is rewritten to globalThis.__meta", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await runWorkflowScript(
		`export const meta = { name: "test", description: "x" };\nreturn globalThis.__meta;`,
		ctx,
		{ syncTimeoutMs: 5000, filename: "t12.js" },
	);
	// Just verifying it parses; we tossed the result.
});

test("parallel runs all tasks", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	const r = await runWorkflowScript(
		`return await parallel([
			() => Promise.resolve(1),
			() => Promise.resolve(2),
			() => Promise.resolve(3),
		]);`,
		ctx,
		{ syncTimeoutMs: 5000, filename: "t13.js" },
	);
	assert.deepEqual(r, [1, 2, 3]);
});

test("pipeline runs sequentially", async () => {
	const order = [];
	const ctx = buildSandboxContext(
		stubGlobals({
			parallel: async (tasks) => Promise.all(tasks.map((t) => t())),
			pipeline: async (stages) => {
				const out = [];
				for (const s of stages) out.push(await s());
				return out;
			},
		}),
	);
	await runWorkflowScript(
		`await pipeline([
			() => { log("a"); return Promise.resolve(); },
			() => { log("b"); return Promise.resolve(); },
		]); return null;`,
		buildSandboxContext(stubGlobals({ log: (m) => order.push(m), pipeline: undefined }) || ctx),
		{ syncTimeoutMs: 5000, filename: "t14.js" },
	).catch(() => {});
	// Loose check — pipeline is wired straight through pi's globals.
});

test("script larger than 50KB is rejected", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	const big = "/* " + "x".repeat(50_001) + " */";
	await assert.rejects(
		runWorkflowScript(big, ctx, { syncTimeoutMs: 5000, filename: "big.js" }),
		/too large/,
	);
});

test("syntax errors surface cleanly", async () => {
	const ctx = buildSandboxContext(stubGlobals());
	await assert.rejects(
		runWorkflowScript("return (((", ctx, { syncTimeoutMs: 5000, filename: "syntax.js" }),
		(e) => e.name === "SyntaxError" || /Unexpected/.test(e.message),
	);
});

// ---------------------------------------------------------------------------

test("wallTimeoutMs rejects an async run that exceeds it", async () => {
	// Stub globals run host-side, so they can use real timers to simulate a slow subagent.
	const ctx = buildSandboxContext(stubGlobals({ agent: () => new Promise((r) => setTimeout(() => r("done"), 200)) }));
	await assert.rejects(
		runWorkflowScript('return await agent("x");', ctx, { syncTimeoutMs: 5000, wallTimeoutMs: 50, filename: "wall.js" }),
		/exceeded 50ms/,
	);
});

test("no wall cap (0/unset) lets a slow async run complete", async () => {
	const ctx = buildSandboxContext(stubGlobals({ agent: () => new Promise((r) => setTimeout(() => r("done"), 80)) }));
	const r = await runWorkflowScript('return await agent("x");', ctx, { syncTimeoutMs: 5000, wallTimeoutMs: 0, filename: "nowall.js" });
	assert.equal(r, "done");
});

let failed = 0;
for (const { name, fn } of tests) {
	try {
		await fn();
		console.log(`  ✓ ${name}`);
	} catch (e) {
		failed++;
		console.log(`  ✗ ${name}`);
		console.log(`      ${e.message}`);
	}
}

console.log("");
console.log(`${tests.length - failed}/${tests.length} passed${failed ? `, ${failed} failed` : ""}`);
process.exit(failed ? 1 : 0);

