	let agentCalls = 0;
	const ctx = buildSandboxContext(stubGlobals({ agent: async () => { agentCalls++; return "x"; } }));
	await assert.rejects(
		runWorkflowScript(`phase("audit", async () => { await agent("do work"); }); return 1;`, ctx, {
			syncTimeoutMs: 5000,
			filename: "phasecb.js",
		}),
		(e) => /takes only a title/.test(e.message) && /does NOT run a callback/.test(e.message),
	);
	assert.equal(agentCalls, 0, "the dropped callback's agent() must not have run");
});

test("phase() with only a title still works", async () => {
