125	 * and `//` + `/* *\/` comments. Does NOT handle regex literals — not needed
126	 * for plain data-shape metadata.
127	 */
128	function extractBalancedBraces(src: string, openIndex: number): string | null {
129		if (src[openIndex] !== "{") return null;
130		let depth = 0;
131		let i = openIndex;
132		while (i < src.length) {
133			const ch = src[i];
134			if (ch === "'" || ch === '"' || ch === "`") {
135				const end = skipString(src, i, ch);
136				if (end < 0) return null;
137				i = end + 1;
138				continue;
139			}
140			if (ch === "/" && src[i + 1] === "/") {
141				const nl = src.indexOf("\n", i);
142				i = nl < 0 ? src.length : nl + 1;
143				continue;
144			}
