146				const close = src.indexOf("*/", i + 2);
147				if (close < 0) return null;
148				i = close + 2;
149				continue;
150			}
151			if (ch === "{") depth++;
152			else if (ch === "}") {
153				depth--;
154				if (depth === 0) return src.slice(openIndex, i + 1);
155			}
156			i++;
157		}
158		return null;
159	}
