161	function skipString(src: string, start: number, quote: string): number {
162		let i = start + 1;
163		while (i < src.length) {
164			const ch = src[i];
165			if (ch === "\\") {
166				i += 2;
167				continue;
168			}
169			if (ch === quote) return i;
170			i++;
171		}
172		return -1;
173	}
