175	function normalizeJsonLikeLiteral(src: string): string {
176		return (
177			src
178				// Single-quoted strings → double-quoted. Safe for our constrained literals;
179				// we don't try to handle escaped quotes inside single-quoted strings.
180				.replace(/'((?:[^'\\]|\\.)*)'/g, (_, body) => '"' + body.replace(/"/g, '\\"') + '"')
