/**
 * Public types for the pi-workflow extension.
 */

export interface WorkflowInput {
	/** Self-contained workflow script (must begin with `export const meta`). Mutually exclusive with `name` and `scriptPath`. */
	script?: string;
	/** @deprecated Claude Code 2.1.146 name for `script`; accepted as an alias. */
	code?: string;
	/** Named workflow (built-in, user, or project). Mutually exclusive with `code` and `scriptPath`. */
	name?: string;
	/** Path to a previously persisted workflow script. Mutually exclusive with `code` and `name`. */
	scriptPath?: string;
	/** Optional value exposed as the `args` global inside the script. */
	args?: unknown;
	/** Replay from a prior run's journal (phase 4). */
	resumeFromRunId?: string;
	/** Launch in the background and return a taskId immediately. */
	background?: boolean;
	/** Return status/progress/result of a prior run instead of starting one. */
	checkRunId?: string;
}

export interface WorkflowAgentCallRecord {
	seq: number;
	prompt: string;
	label?: string;
	model?: string;
	durationMs: number;
	resultPreview: string;
	error?: string;
	/** Real tokens consumed by this subagent (from the run's usage), for budget metering. */
	tokens?: number;
	/** Live lifecycle status for the TUI progress tree. */
	status?: "running" | "done" | "error" | "replayed";
}

export interface WorkflowDetails {
	runId: string;
	scriptPath: string;
	source: "inline" | "named" | "persisted";
	/** Workflow name when resolved via `name` lookup. */
	name?: string;
	phases: string[];
	agentCount: number;
	logs: string[];
	agentCalls: WorkflowAgentCallRecord[];
	startedAt: number;
	durationMs: number;
	error?: string;
}

export interface WorkflowMeta {
	name: string;
	description: string;
	whenToUse?: string;
	phases?: Array<{ title: string; detail?: string }>;
}

