// ── Review-before-run gate (CC 2.1.153 "Review dynamic workflow before running") ──
// Inline (dynamic) scripts pause for explicit user approval + a token-cost notice
// BEFORE any subagent spawns; named/persisted/resume runs are pre-trusted and skip
// it. pi has no managed-settings permission store, so this is the idiomatic pi
// equivalent: an interactive prompt with an env opt-out and a per-session "don't
// ask again". Headless/automation runs (no UI) proceed silently so background and
// pod/harness profiles are never blocked on a prompt.
const REVIEW_RUN = "Run workflow";
const REVIEW_RUN_ALWAYS = "Run — don't ask again this session";
const REVIEW_VIEW = "View script first";
const REVIEW_CANCEL = "Cancel";

let skipReviewThisSession = false;

// Bare env (L4) until the `getExtensionConfig` accessor lands; mirrors
// `workflowsDisabled()`. Truthy → skip the review prompt entirely.
function reviewDisabled(): boolean {
	const v = (process.env.PI_WORKFLOW_NO_CONFIRM ?? "").trim().toLowerCase();
	return v === "1" || v === "true" || v === "yes" || v === "on";
}

/** "Phase: a → b → c" line from meta.phases (accepts string[] or {title}[]). */
function phasesLine(meta: WorkflowMeta | null): string | null {
	const phases = meta?.phases as Array<string | { title?: string }> | undefined;
	if (!Array.isArray(phases) || phases.length === 0) return null;
	const titles = phases
		.map((p) => (typeof p === "string" ? p : p?.title))
		.filter((t): t is string => typeof t === "string" && t.trim() !== "");
	return titles.length ? `Phases: ${titles.join(" → ")}` : null;
}

function buildReviewNotice(meta: WorkflowMeta | null, source: string): string {
	const lines: string[] = ["Run dynamic workflow?", ""];
	if (meta) {
		lines.push(`${meta.name} — ${meta.description}`);
		const ph = phasesLine(meta);
		if (ph) lines.push(ph);
	} else {
		const preview = source.replace(/\s+/g, " ").trim().slice(0, 120);
		lines.push(`(meta unparsed) ${preview}${source.length > 120 ? "…" : ""}`);
	}
	lines.push(
		"",
		`⚠ Spins up subagents (often in parallel) — can burn tokens fast, up to ~${Math.round(DEFAULT_TASK_BUDGET_TOKENS / 1000)}k/run, counted against your usage.`,
		"Stop a foreground run by interrupting the turn (Esc). Disable all dynamic workflows with PI_DISABLE_WORKFLOWS=1.",
	);
	return lines.join("\n");
}

/**
 * Ask the user to review an inline (dynamic) workflow before it runs. Returns
 * "run" to proceed, "cancel" to abort. No-ops to "run" when there is no UI
 * (headless), the user opted out (env), or already chose "don't ask again".
 */
async function reviewDynamicWorkflow(ctx: ExtensionContext, source: string): Promise<"run" | "cancel"> {
	if (skipReviewThisSession || reviewDisabled() || !ctx.hasUI) return "run";
	const notice = buildReviewNotice(parseMetaLiteral(source), source);
	// Loop so "View script first" can show the body, then return to the prompt.
	for (;;) {
		const choice = await ctx.ui.select(notice, [REVIEW_RUN, REVIEW_RUN_ALWAYS, REVIEW_VIEW, REVIEW_CANCEL]);
		if (choice === REVIEW_RUN) return "run";
		if (choice === REVIEW_RUN_ALWAYS) {
			skipReviewThisSession = true;
			return "run";
		}
		if (choice === REVIEW_VIEW) {
			ctx.ui.notify(source.length > 4000 ? `${source.slice(0, 4000)}\n… (truncated)` : source, "info");
			continue;
		}
		return "cancel"; // explicit Cancel, or Esc (undefined)
	}
}

