	lines.push(
		"",
		`⚠ Spins up subagents (often in parallel) — can burn tokens fast, up to ~${Math.round(DEFAULT_TASK_BUDGET_TOKENS / 1000)}k/run, counted against your usage.`,
		"Stop a foreground run by interrupting the turn (Esc). Disable all dynamic workflows with PI_DISABLE_WORKFLOWS=1.",
	);
	return lines.join("\n");
}

/**
 * Ask the user to review an inline (dynamic) workflow before it runs. Returns
 * "run" to proceed, "cancel" to abort. No-ops to "run" when there is no UI
 * (headless), the user opted out (env), or already chose "don't ask again".
 */
async function reviewDynamicWorkflow(ctx: ExtensionContext, source: string): Promise<"run" | "cancel"> {
	if (skipReviewThisSession || reviewDisabled() || !ctx.hasUI) return "run";
	const notice = buildReviewNotice(parseMetaLiteral(source), source);
	// Loop so "View script first" can show the body, then return to the prompt.
	for (;;) {
		const choice = await ctx.ui.select(notice, [REVIEW_RUN, REVIEW_RUN_ALWAYS, REVIEW_VIEW, REVIEW_CANCEL]);
		if (choice === REVIEW_RUN) return "run";
		if (choice === REVIEW_RUN_ALWAYS) {
			skipReviewThisSession = true;
			return "run";
		}
		if (choice === REVIEW_VIEW) {
			ctx.ui.notify(source.length > 4000 ? `${source.slice(0, 4000)}\n… (truncated)` : source, "info");
			continue;
		}
		return "cancel"; // explicit Cancel, or Esc (undefined)
	}
}

