/**
 * Review-before-run gate tests (CC 2.1.153 "Review dynamic workflow before
 * running" parity).
 *
 * Inline (dynamic) scripts must pause for explicit approval + a token-cost
 * notice before anything persists or any subagent spawns. Named/persisted/
 * resume runs are pre-trusted. Headless (no UI) and the env opt-out proceed
 * silently. These exercise the pure helpers + the prompt loop with a mock ctx;
 * no pi boot, no forkAgent.
 *
 * Run: node test/review-gate.test.mjs
 */

import assert from "node:assert/strict";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const mod = await jiti.import("../src/index.ts");
const { reviewDisabled, phasesLine, buildReviewNotice, reviewDynamicWorkflow } = mod;

const tests = [];
const test = (name, fn) => tests.push({ name, fn });

// Mock ctx: select picks an option, notify records calls. select(prompt, options)
// returns the chosen string (or undefined for Esc), matching ctx.ui.select.
const makeCtx = ({ hasUI = true, select, notify } = {}) => {
	const notifications = [];
	return {
		ctx: {
			hasUI,
			ui: {
				select: select ?? (async () => undefined),
				notify: notify ?? ((msg, type) => notifications.push({ msg, type })),
			},
		},
		notifications,
	};
};

const withEnv = async (value, fn) => {
	const prev = process.env.PI_WORKFLOW_NO_CONFIRM;
	if (value === undefined) delete process.env.PI_WORKFLOW_NO_CONFIRM;
	else process.env.PI_WORKFLOW_NO_CONFIRM = value;
	try {
		await fn();
	} finally {
		if (prev === undefined) delete process.env.PI_WORKFLOW_NO_CONFIRM;
		else process.env.PI_WORKFLOW_NO_CONFIRM = prev;
	}
};

// --- reviewDisabled (env opt-out, L4) -------------------------------------

test("reviewDisabled() honours PI_WORKFLOW_NO_CONFIRM truthy forms", async () => {
	for (const v of ["1", "true", "yes", "on", "TRUE", " On "]) {
		await withEnv(v, () => assert.equal(reviewDisabled(), true, `expected ${JSON.stringify(v)} → disabled`));
	}
});

test("reviewDisabled() is false when unset or falsy", async () => {
	await withEnv(undefined, () => assert.equal(reviewDisabled(), false));
	for (const v of ["", "0", "false", "no", "off"]) {
		await withEnv(v, () => assert.equal(reviewDisabled(), false, `expected ${JSON.stringify(v)} → not disabled`));
	}
});

// --- phasesLine (string[] OR {title}[]) -----------------------------------

test("phasesLine renders {title}[] phases", () => {
	const meta = { name: "x", description: "d", phases: [{ title: "Recon" }, { title: "Author" }, { title: "Review" }] };
	assert.equal(phasesLine(meta), "Phases: Recon → Author → Review");
});

test("phasesLine renders string[] phases", () => {
	assert.equal(phasesLine({ name: "x", description: "d", phases: ["Scan", "Fix"] }), "Phases: Scan → Fix");
});

test("phasesLine is null for missing/empty phases", () => {
	assert.equal(phasesLine({ name: "x", description: "d" }), null);
	assert.equal(phasesLine({ name: "x", description: "d", phases: [] }), null);
	assert.equal(phasesLine(null), null);
});

// --- buildReviewNotice (copy + token notice) ------------------------------

test("buildReviewNotice shows name/description/phases + accurate token + stop/disable copy", () => {
	const meta = { name: "draft-goal", description: "Research + draft a goal doc", phases: [{ title: "Recon" }, { title: "Author" }] };
	const notice = buildReviewNotice(meta, 'export const meta = {…}\nphase("Recon")');
	assert.match(notice, /Run dynamic workflow\?/);
	assert.match(notice, /draft-goal — Research \+ draft a goal doc/);
	assert.match(notice, /Phases: Recon → Author/);
	assert.match(notice, /~128k\/run/); // DEFAULT_TASK_BUDGET_TOKENS = 128_000
	assert.match(notice, /counted against your usage/);
	assert.match(notice, /Esc/); // foreground stop hint
	assert.match(notice, /PI_DISABLE_WORKFLOWS=1/); // global kill switch
});

test("buildReviewNotice falls back to a source preview when meta is unparsed", () => {
	const notice = buildReviewNotice(null, "const x = 1; return x;");
	assert.match(notice, /\(meta unparsed\)/);
	assert.match(notice, /const x = 1/);
	assert.match(notice, /~128k\/run/);
});

// --- reviewDynamicWorkflow (decision loop) --------------------------------

test("no UI → runs silently without prompting (headless/pod/harness)", async () => {
	let asked = false;
	const { ctx } = makeCtx({ hasUI: false, select: async () => { asked = true; return undefined; } });
	await withEnv(undefined, async () => {
		assert.equal(await reviewDynamicWorkflow(ctx, "src"), "run");
	});
	assert.equal(asked, false, "must not prompt without a UI");
});

test("env opt-out → runs silently even with a UI", async () => {
	let asked = false;
	const { ctx } = makeCtx({ select: async () => { asked = true; return undefined; } });
	await withEnv("1", async () => {
		assert.equal(await reviewDynamicWorkflow(ctx, "src"), "run");
	});
	assert.equal(asked, false, "env opt-out must skip the prompt");
});

test("selecting Run → returns run", async () => {
	const { ctx } = makeCtx({ select: async (_p, options) => options[0] }); // REVIEW_RUN is first
	await withEnv(undefined, async () => {
		assert.equal(await reviewDynamicWorkflow(ctx, "src"), "run");
	});
});

test("selecting Cancel → returns cancel (nothing runs)", async () => {
	const { ctx } = makeCtx({ select: async (_p, options) => options.find((o) => /cancel/i.test(o)) });
	await withEnv(undefined, async () => {
		assert.equal(await reviewDynamicWorkflow(ctx, "src"), "cancel");
	});
});

test("Esc (undefined) → treated as cancel", async () => {
	const { ctx } = makeCtx({ select: async () => undefined });
	await withEnv(undefined, async () => {
		assert.equal(await reviewDynamicWorkflow(ctx, "src"), "cancel");
	});
});

test("View script first → shows the source, then returns to the prompt", async () => {
	let calls = 0;
	const { ctx, notifications } = makeCtx({
		select: async (_p, options) => {
			calls++;
			return calls === 1 ? options.find((o) => /view/i.test(o)) : options[0]; // view, then Run
		},
	});
	await withEnv(undefined, async () => {
		assert.equal(await reviewDynamicWorkflow(ctx, "THE-SCRIPT-BODY"), "run");
	});
	assert.equal(calls, 2, "should re-prompt after viewing");
	assert.equal(notifications.length, 1);
	assert.match(notifications[0].msg, /THE-SCRIPT-BODY/);
});

// MUST be LAST: sets the module-level session-skip flag, after which every
// reviewDynamicWorkflow call auto-runs for the rest of this process.
test("Run — don't ask again → returns run AND suppresses the next prompt this session", async () => {
	const { ctx } = makeCtx({ select: async (_p, options) => options.find((o) => /don't ask/i.test(o)) });
	await withEnv(undefined, async () => {
		assert.equal(await reviewDynamicWorkflow(ctx, "src"), "run");
	});
	// Second call: a select stub that throws if invoked — proves the prompt is skipped.
	const { ctx: ctx2 } = makeCtx({
		select: async () => {
			throw new Error("must not prompt after 'don't ask again'");
		},
	});
	await withEnv(undefined, async () => {
		assert.equal(await reviewDynamicWorkflow(ctx2, "src"), "run");
	});
});

let failed = 0;
for (const { name, fn } of tests) {
	try {
		await fn();
		console.log(`  ✓ ${name}`);
	} catch (e) {
		failed++;
		console.log(`  ✗ ${name}`);
		console.log(`      ${e.message}`);
	}
}

console.log("");
console.log(`${tests.length - failed}/${tests.length} passed${failed ? `, ${failed} failed` : ""}`);
process.exit(failed ? 1 : 0);

